import { notFound } from "next/navigation";
import Link from "next/link";
import { getBlogsData, getBlogBySlug } from "@/lib/db-helpers";
import { Parallax } from "@/components/ui/Parallax";
import { ArrowLeft, ArrowRight, Clock, Tag, Calendar } from "lucide-react";
import type { Metadata } from "next";

const siteUrl = process.env.NEXT_PUBLIC_APP_URL || "https://www.mark2.in";

export async function generateStaticParams() {
  const blogs = await getBlogsData();
  return (blogs || []).map((post: any) => ({ slug: post.slug }));
}

export const dynamicParams = true;

export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string }>;
}): Promise<Metadata> {
  const { slug } = await params;
  const post = await getBlogBySlug(slug);

  if (!post) {
    return { title: "Article Not Found | MARK Technologies" };
  }

  const canonicalUrl = `${siteUrl}/blog/${post.slug}`;
  const metaTitle = post.metaTitle || `${post.title} | MARK Technologies`;
  const metaDescription = post.metaDescription || post.excerpt;

  return {
    title: metaTitle,
    description: metaDescription,
    alternates: { canonical: canonicalUrl },
    openGraph: {
      title: metaTitle,
      description: metaDescription,
      url: canonicalUrl,
      siteName: "MARK Technologies",
      type: "article",
      publishedTime: post.publishedAt,
      images: [{ url: post.featuredImage || `${siteUrl}/opengraph-image`, width: 1200, height: 630, alt: metaTitle }],
    },
    twitter: {
      card: "summary_large_image",
      title: metaTitle,
      description: metaDescription,
      images: [post.featuredImage || `${siteUrl}/twitter-image`],
    },
  };
}

export default async function BlogPostPage({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;
  const post = await getBlogBySlug(slug);

  if (!post) notFound();

  const allBlogs = await getBlogsData();
  const related = (allBlogs || [])
    .filter((b: any) => b.slug !== slug && b.category === post.category)
    .slice(0, 3);

  const articleSchema = {
    "@context": "https://schema.org",
    "@type": "Article",
    headline: post.title,
    description: post.excerpt,
    author: {
      "@type": "Person",
      name: post.author?.name || "MARK Team",
    },
    publisher: {
      "@type": "Organization",
      name: "MARK Technologies",
      url: siteUrl,
    },
    datePublished: post.publishedAt,
    dateModified: post.updatedAt,
    url: `${siteUrl}/blog/${post.slug}`,
    image: post.featuredImage || `${siteUrl}/opengraph-image`,
  };

  const breadcrumbSchema = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "Home", item: siteUrl },
      { "@type": "ListItem", position: 2, name: "Blog", item: `${siteUrl}/blog` },
      { "@type": "ListItem", position: 3, name: post.title, item: `${siteUrl}/blog/${post.slug}` },
    ],
  };

  return (
    <main className="min-h-screen bg-base">
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(articleSchema) }} />
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbSchema) }} />

      {/* Hero */}
      <div className="pt-24 sm:pt-28 md:pt-32 pb-10 relative overflow-hidden border-b border-[var(--color-border)]">
        <div className="absolute inset-0 pointer-events-none -z-10 overflow-hidden">
          <Parallax speed={0.6} className="absolute top-0 left-1/2 -translate-x-1/2 w-[70vw] h-[70vw] max-w-[900px] max-h-[900px] rounded-full bg-gradient-to-b from-[var(--color-accent)]/8 to-transparent blur-[140px]" />
        </div>
        <div className="container-site relative z-10 max-w-4xl">
          {/* Back link */}
          <Link href="/blog" className="inline-flex items-center gap-2 text-sm text-text-muted hover:text-text-primary transition-colors mb-8 group">
            <ArrowLeft size={14} className="group-hover:-translate-x-0.5 transition-transform" />
            Back to Blog
          </Link>

          {/* Category + Meta */}
          <div className="flex flex-wrap items-center gap-3 mb-5">
            <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-[var(--color-accent-glow)] text-[var(--color-accent-dark)] text-xs font-semibold">
              <Tag size={11} />
              {post.category || "Engineering"}
            </span>
            <span className="flex items-center gap-1 text-xs text-text-muted">
              <Clock size={11} />
              {post.readTime || "5 min read"}
            </span>
            {post.publishedAt && (
              <span className="flex items-center gap-1 text-xs text-text-muted">
                <Calendar size={11} />
                {new Date(post.publishedAt).toLocaleDateString("en-IN", { day: "numeric", month: "long", year: "numeric" })}
              </span>
            )}
          </div>

          <h1 className="text-3xl sm:text-4xl md:text-5xl font-display font-bold text-text-primary leading-tight tracking-tight mb-6 break-words">
            {post.title}
          </h1>

          <p className="text-lg sm:text-xl text-text-secondary leading-relaxed font-light mb-8 break-words">
            {post.excerpt}
          </p>

          {/* Author */}
          <div className="flex items-center gap-3 pt-6 border-t border-[var(--color-border)]">
            <div className="w-10 h-10 rounded-full bg-surface-2 border border-[var(--color-border)] flex items-center justify-center text-sm font-bold text-[var(--color-accent)] uppercase">
              {post.author?.name?.substring(0, 2) || "MK"}
            </div>
            <div>
              <p className="text-sm font-semibold text-text-primary">{post.author?.name || "MARK Team"}</p>
              <p className="text-xs text-text-muted">{post.author?.role || "Engineer, MARK Technologies"}</p>
            </div>
          </div>
        </div>
      </div>

      {/* Featured Image */}
      {post.featuredImage && (
        <div className="container-site max-w-4xl py-8">
          <div className="w-full rounded-2xl overflow-hidden border border-[var(--color-border)]">
            <img src={post.featuredImage} alt={post.title} className="w-full h-auto object-cover max-h-[500px]" />
          </div>
        </div>
      )}

      {/* Article Body */}
      <article className="container-site max-w-4xl py-8 sm:py-12">
      <div
          className="blog-content"
          dangerouslySetInnerHTML={{ __html: post.content }}
        />
      </article>

      {/* Tags */}
      {post.tags && post.tags.length > 0 && (
        <div className="container-site max-w-4xl pb-8">
          <div className="flex flex-wrap gap-2 pt-6 border-t border-[var(--color-border)]">
            {post.tags.map((tag: string) => (
              <span key={tag} className="px-3 py-1 rounded-full bg-surface-2 border border-[var(--color-border)] text-xs text-text-secondary">
                #{tag}
              </span>
            ))}
          </div>
        </div>
      )}

      {/* Related Articles */}
      {related.length > 0 && (
        <section className="section-padding border-t border-[var(--color-border)] bg-surface-2/20">
          <div className="container-site">
            <div className="flex items-center justify-between mb-8">
              <h2 className="text-2xl sm:text-3xl font-display font-bold text-text-primary">More Articles</h2>
              <Link href="/blog" className="text-sm font-semibold text-[var(--color-accent-dark)] hover:underline flex items-center gap-1">
                View all <ArrowRight size={13} />
              </Link>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {related.map((relPost: any) => (
                <Link
                  key={relPost.slug}
                  href={`/blog/${relPost.slug}`}
                  className="group bg-surface-1 border border-[var(--color-border)] rounded-2xl p-6 hover:border-[var(--color-accent)]/40 hover:shadow-xl hover:-translate-y-1 transition-all duration-400 flex flex-col"
                >
                  <span className="text-xs text-[var(--color-accent-dark)] font-semibold mb-2">{relPost.category}</span>
                  <h3 className="text-lg font-display font-bold text-text-primary group-hover:text-[var(--color-accent)] transition-colors mb-2 break-words leading-snug">
                    {relPost.title}
                  </h3>
                  <p className="text-sm text-text-secondary line-clamp-2 mt-auto break-words">{relPost.excerpt}</p>
                  <div className="mt-4 pt-3 border-t border-[var(--color-border)]/60 text-xs font-semibold text-[var(--color-accent-dark)] flex items-center gap-1">
                    Read Article <ArrowRight size={11} />
                  </div>
                </Link>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* CTA */}
      <section className="container-site py-12 sm:py-16">
        <div className="rounded-2xl bg-text-primary text-surface-1 p-8 sm:p-12 text-center relative overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-[var(--color-accent)]/20 rounded-full blur-3xl pointer-events-none" />
          <div className="relative z-10">
            <p className="text-xs font-mono uppercase tracking-widest text-[var(--color-accent-light)] mb-3">Work With Us</p>
            <h2 className="text-2xl sm:text-3xl font-display font-bold mb-4">Have a project in mind?</h2>
            <p className="text-surface-2 text-sm sm:text-base mb-6 font-light max-w-lg mx-auto">
              Whether it is a website, ERP system, or a full-stack platform — let us have a technical scoping conversation.
            </p>
            <Link
              href="/contact"
              className="inline-flex items-center gap-2 px-8 py-3.5 rounded-full bg-[var(--color-accent)] text-surface-1 font-semibold text-sm hover:bg-[var(--color-accent-light)] transition-colors"
            >
              Start a Project <ArrowRight size={16} />
            </Link>
          </div>
        </div>
      </section>
    </main>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { getBlogsData } from "@/lib/db-helpers";
import { Parallax } from "@/components/ui/Parallax";
import { SectionHeading } from "@/components/ui/SectionHeading";
import { ArrowUpRight, Clock, Tag } from "lucide-react";

const siteUrl = process.env.NEXT_PUBLIC_APP_URL || "https://www.mark2.in";

export const metadata: Metadata = {
  title: "Blog — Engineering Insights & Technical Articles",
  description: "Technical articles, engineering guides, and insights from the MARK Technologies team on web development, ERP systems, SEO, and software architecture.",
  alternates: {
    canonical: `${siteUrl}/blog`,
  },
  openGraph: {
    title: "Blog — Engineering Insights | MARK Technologies",
    description: "Technical articles and engineering insights from the MARK Technologies team.",
    url: `${siteUrl}/blog`,
    siteName: "MARK Technologies",
    type: "website",
    images: [{ url: `${siteUrl}/opengraph-image`, width: 1200, height: 630, alt: "Blog — MARK Technologies" }],
  },
  twitter: {
    card: "summary_large_image",
    title: "Blog — Engineering Insights | MARK Technologies",
    description: "Technical articles and engineering insights from the MARK Technologies team.",
    images: [`${siteUrl}/twitter-image`],
  },
};

export default async function BlogPage() {
  const blogs = await getBlogsData();

  const breadcrumbSchema = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "Home", item: siteUrl },
      { "@type": "ListItem", position: 2, name: "Blog", item: `${siteUrl}/blog` },
    ],
  };

  const categories = blogs.length > 0
    ? ["All", ...Array.from(new Set(blogs.map((b: any) => b.category).filter(Boolean)))]
    : [];

  return (
    <>
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbSchema) }} />

      {/* Hero */}
      <div className="pt-24 sm:pt-28 md:pt-32 pb-10 sm:pb-12 relative overflow-hidden">
        <div className="absolute inset-0 pointer-events-none -z-10 overflow-hidden">
          <Parallax speed={0.8} className="absolute top-0 left-1/2 -translate-x-1/2 w-[60vw] h-[60vw] max-w-[800px] max-h-[800px] rounded-full bg-gradient-to-b from-[var(--color-accent)]/10 to-transparent blur-[120px]" />
        </div>
        <div className="container-site relative z-10">
          <SectionHeading
            as="h1"
            title="Engineering insights from the team."
            subtitle="Technical articles, guides, and lessons from building real products — websites, ERPs, and digital platforms for clients across India."
            badge="Blog"
            align="center"
          />
        </div>
      </div>

      {/* Blog Grid */}
      <section className="section-padding bg-base">
        <div className="container-site">
          {blogs.length === 0 ? (
            <div className="text-center py-24">
              <p className="text-text-muted text-lg">No articles published yet. Check back soon.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 sm:gap-8">
              {blogs.map((post: any, index: number) => (
                <Link
                  key={post._id || post.slug}
                  href={`/blog/${post.slug}`}
                  className={`group flex flex-col bg-surface-1 border border-[var(--color-border)] rounded-2xl overflow-hidden hover:border-[var(--color-accent)]/40 hover:shadow-2xl hover:-translate-y-1 transition-all duration-500 ${index === 0 ? "md:col-span-2 lg:col-span-2" : ""}`}
                >
                  {/* Featured image or gradient placeholder */}
                  <div className={`relative w-full bg-gradient-to-br from-surface-2 to-[var(--color-accent)]/5 overflow-hidden ${index === 0 ? "h-64 sm:h-80" : "h-48"}`}>
                    {post.featuredImage ? (
                      <img
                        src={post.featuredImage}
                        alt={post.title}
                        className="w-full h-full object-cover grayscale group-hover:grayscale-0 group-hover:scale-105 transition-all duration-700"
                      />
                    ) : (
                      <div className="absolute inset-0 flex items-center justify-center">
                        <span className="text-6xl sm:text-8xl font-display font-bold text-[var(--color-accent)]/10 select-none">
                          {post.category?.substring(0, 2).toUpperCase() || "MK"}
                        </span>
                      </div>
                    )}
                    {/* Category badge */}
                    <div className="absolute top-4 left-4">
                      <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-black/60 backdrop-blur-sm text-white text-xs font-medium">
                        <Tag size={10} />
                        {post.category || "Engineering"}
                      </span>
                    </div>
                  </div>

                  {/* Content */}
                  <div className="flex flex-col flex-1 p-5 sm:p-6 md:p-8">
                    <div className="flex items-center gap-3 text-xs text-text-muted mb-3 flex-wrap">
                      <span className="flex items-center gap-1">
                        <Clock size={11} />
                        {post.readTime || "5 min read"}
                      </span>
                      {post.publishedAt && (
                        <span>
                          {new Date(post.publishedAt).toLocaleDateString("en-IN", {
                            day: "numeric",
                            month: "short",
                            year: "numeric",
                          })}
                        </span>
                      )}
                    </div>

                    <h2 className={`font-display font-bold text-text-primary group-hover:text-[var(--color-accent)] transition-colors mb-3 leading-snug break-words ${index === 0 ? "text-2xl sm:text-3xl" : "text-xl sm:text-2xl"}`}>
                      {post.title}
                    </h2>

                    <p className="text-text-secondary text-sm sm:text-base leading-relaxed line-clamp-3 mb-6 flex-1 break-words">
                      {post.excerpt}
                    </p>

                    <div className="flex items-center justify-between mt-auto pt-4 border-t border-[var(--color-border)] group-hover:border-[var(--color-accent)]/20 transition-colors">
                      <div className="flex items-center gap-2.5">
                        <div className="w-7 h-7 rounded-full bg-surface-2 border border-[var(--color-border)] flex items-center justify-center text-xs font-bold text-text-secondary uppercase">
                          {post.author?.name?.substring(0, 2) || "MK"}
                        </div>
                        <div>
                          <p className="text-xs font-medium text-text-primary">{post.author?.name || "MARK Team"}</p>
                          <p className="text-xs text-text-muted">{post.author?.role || "Engineer"}</p>
                        </div>
                      </div>
                      <div className="w-8 h-8 rounded-full border border-[var(--color-border)] flex items-center justify-center text-text-muted opacity-0 -translate-x-2 group-hover:opacity-100 group-hover:translate-x-0 group-hover:bg-[var(--color-accent)] group-hover:text-white group-hover:border-[var(--color-accent)] transition-all duration-400">
                        <ArrowUpRight size={15} />
                      </div>
                    </div>
                  </div>
                </Link>
              ))}
            </div>
          )}
        </div>
      </section>
    </>
  );
}

import { notFound } from "next/navigation";
import Link from "next/link";
import type { Metadata } from "next";
import {
  getClientBySlug,
  getClientsData,
  getPortfolioBySlug,
} from "@/lib/db-helpers";
import type { Client, PortfolioItem } from "@/lib/types";
import { Parallax } from "@/components/ui/Parallax";
import {
  ArrowLeft,
  ArrowRight,
  ArrowUpRight,
  ExternalLink,
  CheckCircle2,
  Building2,
  Calendar,
  MapPin,
  Users,
  Quote,
  ShieldCheck,
  Layers,
  Cpu,
  Sparkles,
} from "lucide-react";

export const dynamicParams = true;

export async function generateStaticParams() {
  const clients = await getClientsData();
  return clients.map((c: Client) => ({
    slug: c.slug,
  }));
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string }>;
}): Promise<Metadata> {
  const { slug } = await params;
  const client = await getClientBySlug(slug);

  if (!client) {
    return {
      title: "Client Partner Not Found | MARK Technologies",
      description: "The requested client partnership profile could not be found.",
    };
  }

  const siteUrl = process.env.NEXT_PUBLIC_APP_URL || "https://www.mark2.in";
  const canonicalUrl = `${siteUrl}/clients/${client.slug}`;
  const title = `${client.name} — Partnership & Engineering Case Profile | MARK Technologies`;
  const description =
    client.tagline ||
    client.description ||
    `Discover how MARK partnered with ${client.name} to engineer scalable digital systems and cloud architecture.`;

  return {
    title,
    description,
    alternates: {
      canonical: canonicalUrl,
    },
    openGraph: {
      title,
      description,
      url: canonicalUrl,
      siteName: "MARK Technologies",
      type: "article",
      images: [
        {
          url: `${siteUrl}/opengraph-image`,
          width: 1200,
          height: 630,
          alt: `${client.name} Partnership — MARK Technologies`,
        },
      ],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [`${siteUrl}/twitter-image`],
    },
  };
}

export default async function ClientDetailPage({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;
  const [client, allClients] = await Promise.all([
    getClientBySlug(slug),
    getClientsData(),
  ]);

  if (!client) {
    notFound();
  }

  // Related portfolio project if specified
  let relatedProject: PortfolioItem | null = null;
  if (client.caseStudySlug) {
    relatedProject = (await getPortfolioBySlug(client.caseStudySlug)) as PortfolioItem | null;
  }

  const siteUrl = process.env.NEXT_PUBLIC_APP_URL || "https://www.mark2.in";
  const canonicalUrl = `${siteUrl}/clients/${client.slug}`;

  // Find next and previous clients for navigation
  const currentIndex = allClients.findIndex((c: Client) => c.slug === client.slug);
  const prevClient =
    currentIndex > 0
      ? allClients[currentIndex - 1]
      : allClients[allClients.length - 1];
  const nextClient =
    currentIndex < allClients.length - 1
      ? allClients[currentIndex + 1]
      : allClients[0];

  const initialLetters = client.name
    .split(" ")
    .map((n: string) => n[0])
    .slice(0, 2)
    .join("")
    .toUpperCase();

  const breadcrumbSchema = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      {
        "@type": "ListItem",
        position: 1,
        name: "Home",
        item: siteUrl,
      },
      {
        "@type": "ListItem",
        position: 2,
        name: "Clients",
        item: `${siteUrl}/clients`,
      },
      {
        "@type": "ListItem",
        position: 3,
        name: client.name,
        item: canonicalUrl,
      },
    ],
  };

  const organizationSchema = {
    "@context": "https://schema.org",
    "@type": "Organization",
    name: client.name,
    url: client.website || canonicalUrl,
    description: client.description,
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbSchema) }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(organizationSchema) }}
      />

      <div className="pt-28 pb-20 min-h-screen relative overflow-hidden bg-base">
        {/* Background Ambient Glow */}
        <div className="absolute inset-0 pointer-events-none -z-10 overflow-hidden">
          <Parallax
            speed={0.6}
            className="absolute top-0 right-1/4 w-[50vw] h-[50vw] max-w-[700px] max-h-[700px] rounded-full bg-gradient-to-bl from-[var(--color-accent)]/15 via-[var(--color-accent)]/5 to-transparent blur-[140px]"
          />
        </div>

        <div className="container-site max-w-6xl">
          {/* Top Breadcrumb Navigation */}
          <div className="flex items-center justify-between gap-4 mb-8">
            <Link
              href="/clients"
              className="inline-flex items-center gap-2 text-xs font-medium text-text-muted hover:text-text-primary transition-colors group"
            >
              <ArrowLeft
                size={14}
                className="group-hover:-translate-x-1 transition-transform"
              />
              <span>Back to All Clients</span>
            </Link>

            <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium bg-[var(--color-accent)]/10 text-[var(--color-accent-dark)] border border-[var(--color-accent)]/20">
              <ShieldCheck size={13} />
              <span>Verified Enterprise Partner</span>
            </span>
          </div>

          {/* Hero Header Card */}
          <div className="rounded-3xl border border-[var(--color-border)] bg-surface-1/90 backdrop-blur-xl p-5 sm:p-8 md:p-12 mb-8 sm:mb-10 shadow-sm relative overflow-hidden">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 sm:gap-8 pb-6 sm:pb-8 border-b border-[var(--color-border)]">
              <div className="flex flex-col xs:flex-row items-start xs:items-center gap-4 sm:gap-5 min-w-0">
                <div className="w-16 h-16 sm:w-20 sm:h-20 md:w-24 md:h-24 rounded-2xl bg-surface-2 border border-[var(--color-border)] flex items-center justify-center font-display font-bold text-xl sm:text-2xl md:text-3xl text-text-primary shadow-sm overflow-hidden p-2 shrink-0">
                  {client.logoUrl ? (
                    <img
                      src={client.logoUrl}
                      alt={client.name}
                      className="w-full h-full object-contain"
                    />
                  ) : (
                    <span>{initialLetters}</span>
                  )}
                </div>
                <div className="min-w-0">
                  <h1 className="text-2xl sm:text-3xl md:text-4xl font-display font-bold text-text-primary break-words">
                    {client.name}
                  </h1>
                  <div className="flex flex-wrap items-center gap-2 sm:gap-3 mt-2">
                    <span className="px-2.5 sm:px-3 py-0.5 sm:py-1 rounded-full text-xs font-medium bg-[var(--color-accent)]/10 text-[var(--color-accent-dark)] border border-[var(--color-accent)]/20">
                      {client.industry}
                    </span>
                    {client.location && (
                      <span className="flex items-center gap-1 text-xs text-text-secondary">
                        <MapPin size={13} className="text-text-muted" />
                        {client.location}
                      </span>
                    )}
                    {client.companySize && (
