import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { getTeamMemberBySlug, getTeamData } from "@/lib/db-helpers";
import { Badge } from "@/components/ui/Badge";
import { Link as LinkIcon, Globe, MessageSquare, ArrowLeft, Calendar, Award, Briefcase } from "lucide-react";
import Link from "next/link";
import { Button } from "@/components/ui/Button";

export async function generateStaticParams() {
  const members = await getTeamData();
  return members.map((member: any) => ({
    slug: member.slug,
  }));
}

export async function generateMetadata({ params }: { params: Promise<{ slug: string }> }): Promise<Metadata> {
  const { slug } = await params;
  const member = await getTeamMemberBySlug(slug);
  if (!member) return { title: "Member Not Found" };

  const siteUrl = process.env.NEXT_PUBLIC_APP_URL || "https://www.mark2.in";
  const canonicalUrl = `${siteUrl}/team/${member.slug}`;
  const title = `${member.name} — ${member.role} | MARK Technologies`;
  const description = member.bio || `${member.name} is a ${member.role} at MARK Technologies specializing in ${member.specialization || "software engineering"}.`;

  return {
    title,
    description,
    alternates: {
      canonical: canonicalUrl,
    },
    openGraph: {
      title,
      description,
      url: canonicalUrl,
      siteName: "MARK Technologies",
      type: "profile",
      images: [
        {
          url: member.photo || `${siteUrl}/opengraph-image`,
          width: 1200,
          height: 630,
          alt: title,
        },
      ],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [member.photo || `${siteUrl}/twitter-image`],
    },
  };
}

export default async function TeamMemberPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const member = await getTeamMemberBySlug(slug);

  if (!member) {
    notFound();
  }

  const techTags = member.techTags || [];
  const certifications = member.certifications || [];
  const siteUrl = process.env.NEXT_PUBLIC_APP_URL || "https://www.mark2.in";
  const memberUrl = `${siteUrl}/team/${member.slug}`;

  const breadcrumbSchema = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      {
        "@type": "ListItem",
        position: 1,
        name: "Home",
        item: siteUrl,
      },
      {
        "@type": "ListItem",
        position: 2,
        name: "Team",
        item: `${siteUrl}/team`,
      },
      {
        "@type": "ListItem",
        position: 3,
        name: member.name,
        item: memberUrl,
      },
    ],
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbSchema) }}
      />
      <div className="pt-24 sm:pt-28 md:pt-32 pb-12 sm:pb-16 min-h-screen">
        <div className="container-site max-w-4xl">
          <Link href="/team" className="inline-flex items-center gap-2 text-text-muted hover:text-text-primary transition-colors mb-6 sm:mb-8">
            <ArrowLeft size={16} /> Back to Team
          </Link>

        <div className="grid grid-cols-1 md:grid-cols-[1fr_2fr] gap-8 md:gap-12 items-start">
          {/* Left Column - Profile Card */}
          <div className="bg-surface-1 border border-[var(--color-border)] rounded-[var(--radius-lg)] p-5 sm:p-6 md:p-8 text-center sticky top-28 md:top-32">
            <div className="w-32 h-32 mx-auto rounded-full bg-surface-2 mb-6 flex items-center justify-center text-text-muted text-4xl font-bold uppercase overflow-hidden border-2 border-surface-2">
              {member.photo ? (
                <img src={member.photo} alt={member.name} className="w-full h-full object-cover" />
              ) : (
                member.name.substring(0, 2)
              )}
            </div>

            <h1 className="text-display-sm mb-2">{member.name}</h1>
            <p className="text-accent font-medium mb-6">{member.role}</p>

            <div className="flex justify-center gap-4 mb-8">
              {member.socialLinks?.linkedin && (
                <a href={member.socialLinks.linkedin} target="_blank" rel="noopener noreferrer" className="p-3 bg-surface-2 rounded-full text-text-muted hover:text-[#0A66C2] hover:bg-surface-2/80 transition-all"><LinkIcon size={20} /></a>
              )}
              {member.socialLinks?.github && (
                <a href={member.socialLinks.github} target="_blank" rel="noopener noreferrer" className="p-3 bg-surface-2 rounded-full text-text-muted hover:text-text-primary hover:bg-surface-2/80 transition-all"><Globe size={20} /></a>
              )}
              {member.socialLinks?.twitter && (
                <a href={member.socialLinks.twitter} target="_blank" rel="noopener noreferrer" className="p-3 bg-surface-2 rounded-full text-text-muted hover:text-[#1DA1F2] hover:bg-surface-2/80 transition-all"><MessageSquare size={20} /></a>
              )}
            </div>

            <div className="space-y-4 text-left text-[var(--text-body-sm)]">
              {member.yearsExperience && (
                <div className="flex items-center gap-3 text-text-secondary">
                  <Briefcase size={16} className="text-text-muted" />
                  <span>{member.yearsExperience}+ Years Exp.</span>
                </div>
              )}
              {member.joinedDate && (
                <div className="flex items-center gap-3 text-text-secondary">
                  <Calendar size={16} className="text-text-muted" />
                  <span>Joined {member.joinedDate}</span>
                </div>
              )}
              {certifications.length > 0 && (
                <div className="flex items-start gap-3 text-text-secondary">
                  <Award size={16} className="text-text-muted mt-1 shrink-0" />
                  <span>{certifications[0]} {certifications.length > 1 && `+${certifications.length - 1} more`}</span>
                </div>
              )}
            </div>

            <Button className="w-full mt-8" href="/contact">Hire Our Team</Button>
          </div>

          {/* Right Column - Content */}
          <div className="prose prose-invert max-w-none">
            <h2 className="text-display-xs mb-6 pb-4 border-b border-[var(--color-border)]">About {member.name.split(' ')[0]}</h2>
            <div className="text-text-secondary text-lg leading-relaxed space-y-6 whitespace-pre-wrap">
              {member.bio || `${member.name} is a senior engineering specialist with extensive experience designing resilient architectures, intuitive interfaces, and enterprise software systems.`}
            </div>

            {member.specialization && (
              <>
                <h3 className="text-xl font-bold mt-12 mb-6 text-text-primary">Specialization</h3>
                <p className="text-text-secondary mb-8">{member.specialization}</p>
              </>
            )}

            {techTags.length > 0 && (
              <>
                <h3 className="text-xl font-bold mt-12 mb-6 text-text-primary">Core Tech Stack</h3>
                <div className="flex flex-wrap gap-3">
                  {techTags.map((tag: string) => (
                    <Badge key={tag} variant="outline" size="md">{tag}</Badge>
                  ))}
                </div>
              </>
            )}

            {member.currentlyWorkingOn && (
              <div className="mt-8 sm:mt-12 p-4 sm:p-6 bg-accent/5 border border-accent/20 rounded-[var(--radius-md)]">
                <p className="text-sm font-medium text-accent mb-2 uppercase tracking-wider">Currently Working On</p>
                <p className="text-text-primary">{member.currentlyWorkingOn}</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
    </>
  );
}

"use client";

import { useEffect, useState } from "react";
import { AdminHeader } from "@/components/admin/AdminHeader";
import { DataTable, Column } from "@/components/admin/DataTable";
import { Modal } from "@/components/admin/Modal";
import { ConfirmDialog } from "@/components/admin/ConfirmDialog";
import { FormTabs, FormTabItem } from "@/components/admin/FormTabs";
import { SlugInput } from "@/components/admin/SlugInput";
import { ArrayInput } from "@/components/admin/ArrayInput";
import { SeoHelperInputs } from "@/components/admin/SeoHelperInputs";
import { ImageUploadInput } from "@/components/admin/ImageUploadInput";
import { FormField } from "@/components/admin/FormField";
import { StatusBreakdownBar } from "@/components/admin/StatusBreakdownBar";
import { useToast } from "@/components/admin/Toast";
import {
  Edit2,
  Trash2,
  Plus,
  BookOpen,
  ExternalLink,
  Layers,
  FileText,
  Search,
  Check,
  Eye,
} from "lucide-react";

const categories = ["Engineering", "Product", "Architecture", "Design", "AI & Automation"];
const statuses = ["published", "draft", "archived"];

export default function BlogAdminPage() {
  const [posts, setPosts] = useState<any[]>([]);
  const [statusFilter, setStatusFilter] = useState("all");
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingPost, setEditingPost] = useState<any | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState("general");
  const [formLoading, setFormLoading] = useState(false);
  const [formError, setFormError] = useState("");
  const { success, error: toastError } = useToast();

  const [formData, setFormData] = useState({
    title: "",
    slug: "",
    excerpt: "",
    content: "",
    featuredImage: "",
    category: "Engineering",
    tags: [] as string[],
    authorName: "MARK Team",
    authorRole: "Technical Architect",
    status: "published",
    metaTitle: "",
    metaDescription: "",
    readTime: "5 min read",
  });

  const fetchPosts = async () => {
    setIsLoading(true);
    try {
      const res = await fetch("/api/admin/blog");
      const data = await res.json();
      if (res.ok) setPosts(data.posts || []);
    } catch (err) {
      console.error("Error fetching posts", err);
      toastError("Failed to load blog posts");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchPosts();
  }, []);

  const openCreateModal = () => {
    setEditingPost(null);
    setActiveTab("general");
    setFormData({
      title: "",
      slug: "",
      excerpt: "",
      content: "",
      featuredImage: "",
      category: "Engineering",
      tags: ["Next.js", "Architecture", "TypeScript"],
      authorName: "MARK Team",
      authorRole: "Technical Architect",
      status: "published",
      metaTitle: "",
      metaDescription: "",
      readTime: "5 min read",
    });
    setFormError("");
    setIsModalOpen(true);
  };

  const openEditModal = (post: any) => {
    setEditingPost(post);
    setActiveTab("general");
    setFormData({
      title: post.title || "",
      slug: post.slug || "",
      excerpt: post.excerpt || "",
      content: post.content || "",
      featuredImage: post.featuredImage || "",
      category: post.category || "Engineering",
      tags: Array.isArray(post.tags) ? post.tags : [],
      authorName: post.author?.name || "MARK Team",
      authorRole: post.author?.role || "Technical Architect",
      status: post.status || "published",
      metaTitle: post.metaTitle || "",
      metaDescription: post.metaDescription || "",
      readTime: post.readTime || "5 min read",
    });
    setFormError("");
    setIsModalOpen(true);
  };

  const handleTitleChange = (val: string) => {
    setFormData((prev) => ({
      ...prev,
      title: val,
      slug: prev.slug || val.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""),
    }));
  };

  const handleToggleStatus = async (post: any) => {
    const nextStatus = post.status === "published" ? "draft" : "published";
    try {
      const res = await fetch(`/api/admin/blog/${post._id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: nextStatus }),
      });
      if (res.ok) {
        setPosts((prev) =>
          prev.map((p) => (p._id === post._id ? { ...p, status: nextStatus } : p))
        );
        success(`Post marked as ${nextStatus.toUpperCase()}`);
      } else {
        toastError("Failed to update status");
      }
    } catch (err) {
      toastError("Error updating post status");
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setFormLoading(true);
    setFormError("");

    const payload = {
      ...formData,
      author: {
        name: formData.authorName,
        role: formData.authorRole,
      },
    };

    try {
      const url = editingPost
        ? `/api/admin/blog/${editingPost._id}`
        : `/api/admin/blog`;
      const method = editingPost ? "PUT" : "POST";

      const res = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Failed to save post");
      }

      setIsModalOpen(false);
      fetchPosts();
      success(editingPost ? "Article updated successfully!" : "Article published successfully!");
    } catch (err: any) {
      setFormError(err.message || "An unexpected error occurred");
      toastError(err.message || "An unexpected error occurred");
    } finally {
      setFormLoading(false);
    }
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    try {
      const res = await fetch(`/api/admin/blog/${deleteId}`, { method: "DELETE" });
      if (res.ok) {
        setDeleteId(null);
        fetchPosts();
        success("Article deleted successfully");
      } else {
        toastError("Failed to delete article");
      }
    } catch (err) {
      toastError("Error deleting article");
    }
  };

  const tabs: FormTabItem[] = [
    { id: "general", label: "General & Author", icon: Layers },
    { id: "content", label: "Article Content", icon: FileText },
    { id: "seo", label: "Tags & SEO", icon: Search },
  ];

  const wordCount = formData.content
    ? formData.content.trim().split(/\s+/).filter(Boolean).length
    : 0;

  const filteredPosts = posts.filter((post) => {
    if (statusFilter === "all") return true;
    return post.status === statusFilter;
  });

  const columns: Column<any>[] = [
    {
      header: "Article",
      cell: (row) => (
        <div className="flex items-center gap-3">
          {row.featuredImage ? (
            <img src={row.featuredImage} alt={row.title} className="w-10 h-10 rounded-lg object-cover border border-[var(--color-border)]" />
          ) : (
            <div className="w-10 h-10 rounded-lg bg-[var(--color-accent-glow)] text-[var(--color-accent-dark)] flex items-center justify-center">
              <BookOpen size={16} />
            </div>
          )}
          <div>
            <div className="font-semibold text-text-primary text-xs">{row.title}</div>
            <div className="text-[11px] text-text-muted font-mono">
              {row.category} • {row.readTime || "5 min read"}
            </div>
          </div>
        </div>
      ),
    },
    {
      header: "Author",
      cell: (row) => (
        <div className="text-xs">
          <p className="font-medium text-text-primary">{row.author?.name || "MARK Team"}</p>
          <p className="text-[10px] text-text-muted">{row.author?.role || "Architect"}</p>
        </div>
      ),
    },
    {
      header: "Status",
      cell: (row) => (
        <button
          type="button"
          onClick={() => handleToggleStatus(row)}
          className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold cursor-pointer transition-all ${
            row.status === "published"
              ? "bg-emerald-500/10 text-emerald-600 hover:bg-emerald-500/20"
              : row.status === "draft"
              ? "bg-amber-500/10 text-amber-600 hover:bg-amber-500/20"
              : "bg-zinc-500/10 text-zinc-500"
          }`}
          title="Click to toggle published status"
        >
          {row.status === "published" ? "● Published" : "○ Draft"}
        </button>
      ),
    },
    {
      header: "Actions",
      className: "text-right",
      cell: (row) => (
        <div className="flex items-center justify-end gap-1.5">
          <a
            href={`/blog/${row.slug}`}
            target="_blank"
            rel="noopener noreferrer"
            className="p-1.5 rounded-md hover:bg-surface-3 text-text-muted hover:text-text-primary transition-colors"
            title="View Live Article"
          >
            <ExternalLink size={14} />
          </a>
          <button
            onClick={() => openEditModal(row)}
            className="p-1.5 rounded-md hover:bg-surface-3 text-text-secondary hover:text-text-primary transition-colors cursor-pointer"
            title="Edit Article"
          >
            <Edit2 size={14} />
          </button>
          <button
            onClick={() => setDeleteId(row._id)}
            className="p-1.5 rounded-md hover:bg-red-500/10 text-text-muted hover:text-red-600 transition-colors cursor-pointer"
            title="Delete Article"
          >
            <Trash2 size={14} />
          </button>
        </div>
      ),
    },
  ];

  return (
    <div className="flex-1 flex flex-col">
      <AdminHeader
        title="Engineering Insights & Blog"
        description="Publish, edit, and organize architectural thought leadership, case studies, and engineering essays"
        actionButton={{
          label: "Add Article",
          onClick: openCreateModal,
          icon: Plus,
        }}
        onRefresh={fetchPosts}
        isLoading={isLoading}
      />

      <div className="p-6 sm:p-8 max-w-7xl space-y-4">
        <StatusBreakdownBar
          items={[
            { id: "all", label: "All Articles", count: posts.length },
            { id: "published", label: "Published", count: posts.filter((p) => p.status === "published").length, color: "emerald" },
            { id: "draft", label: "Drafts", count: posts.filter((p) => p.status === "draft").length, color: "amber" },
            { id: "archived", label: "Archived", count: posts.filter((p) => p.status === "archived").length, color: "zinc" },
          ]}
          activeFilter={statusFilter}
          onFilterChange={setStatusFilter}
        />

        <DataTable
          columns={columns}
          data={filteredPosts}
          searchPlaceholder="Search articles by headline or tag..."
          searchKey="title"
          isLoading={isLoading}
          emptyMessage="No articles found for this status. Click 'Add Article' to publish engineering insights."
        />
      </div>

      {/* Modal with Pinned Footer and Tabs */}
      <Modal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        title={editingPost ? `Edit Article: ${editingPost.title}` : "Create Engineering Article"}
        description="Draft, edit, and format thought leadership with live word counters and SEO optimization."
        maxWidth="4xl"
        footer={
          <div className="flex items-center justify-between w-full">
            <div>
              {editingPost && formData.slug && (
                <a
                  href={`/blog/${formData.slug}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex items-center gap-1.5 text-xs text-[var(--color-accent-dark)] hover:underline font-medium"
                >
                  <ExternalLink size={13} />
                  <span>View on Live Site</span>
                </a>
              )}
            </div>
            <div className="flex items-center gap-2.5">
              <button
                type="button"
                onClick={() => setIsModalOpen(false)}
                className="px-4 py-2 text-xs font-semibold rounded-lg bg-surface-2 hover:bg-surface-3 text-text-secondary transition-colors cursor-pointer"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={handleSave}
                disabled={formLoading}
                className="px-5 py-2 text-xs font-semibold rounded-lg bg-text-primary text-surface-1 hover:bg-text-secondary transition-all disabled:opacity-50 cursor-pointer shadow-md flex items-center gap-1.5"
              >
                {formLoading ? (
                  <span>Saving...</span>
                ) : (
                  <>
                    <Check size={14} />
                    <span>{editingPost ? "Update Article" : "Publish Article"}</span>
                  </>
                )}
              </button>
            </div>
          </div>
        }
      >
        {formError && (
          <div className="mb-4 p-3 bg-red-500/10 border border-red-500/20 text-red-600 text-xs rounded-lg">
            {formError}
          </div>
        )}

        <form onSubmit={handleSave} className="space-y-4">
          <FormTabs tabs={tabs} activeTab={activeTab} onChange={setActiveTab} />

          {/* TAB 1: GENERAL & AUTHOR */}
          {activeTab === "general" && (
            <div className="space-y-4 animate-in fade-in duration-150">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <FormField
                  label="Article Title"
                  required
                  tooltip="Headline displayed in the blog card, main banner, and social share links."
                  charCount={{ current: formData.title.length, optimal: { min: 30, max: 80 }, max: 120 }}
                >
                  <input
                    type="text"
                    required
                    value={formData.title}
                    onChange={(e) => handleTitleChange(e.target.value)}
                    placeholder="e.g. Distributed State Synchronization in Next.js 15"
                    className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
                  />
                </FormField>

                <div>
                  <SlugInput
                    value={formData.slug}
                    onChange={(slug) => setFormData({ ...formData, slug })}
                    titleValue={formData.title}
                    pathPrefix="/blog/"
                    isExisting={Boolean(editingPost)}
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <FormField
                  label="Topic Category"
                  required
                  tooltip="Primary subject category used to filter articles on the public /blog index."
                >
                  <select
                    value={formData.category}
                    onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                    className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
                  >
                    {categories.map((cat) => (
                      <option key={cat} value={cat}>
                        {cat}
                      </option>
                    ))}
                  </select>
                </FormField>

                <FormField
                  label="Publish Status"
                  tooltip="Controls public accessibility: Draft hides the post; Published exposes it on the live blog."
                >
                  <select
                    value={formData.status}
                    onChange={(e) => setFormData({ ...formData, status: e.target.value })}
                    className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
                  >
                    {statuses.map((s) => (
                      <option key={s} value={s}>
                        {s.charAt(0).toUpperCase() + s.slice(1)}
                      </option>
                    ))}
                  </select>
                </FormField>

                <FormField
                  label="Estimated Read Time"
                  tooltip="Displayed on blog listing cards and the article header (e.g. '5 min read')."
                >
                  <input
                    type="text"
                    value={formData.readTime}
                    onChange={(e) => setFormData({ ...formData, readTime: e.target.value })}
                    placeholder="e.g. 6 min read"
                    className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
                  />
                </FormField>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <FormField
                  label="Author Name"
                  tooltip="Byline author credited on the article header and metadata."
                >
                  <input
                    type="text"
                    value={formData.authorName}
                    onChange={(e) => setFormData({ ...formData, authorName: e.target.value })}
                    placeholder="e.g. MARK Team"
                    className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
                  />
                </FormField>

                <FormField
                  label="Author Role / Title"
                  tooltip="Professional engineering title displayed beside the author avatar (e.g. Principal System Architect)."
                >
                  <input
                    type="text"
                    value={formData.authorRole}
                    onChange={(e) => setFormData({ ...formData, authorRole: e.target.value })}
                    placeholder="e.g. Principal System Architect"
                    className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
                  />
                </FormField>
              </div>
            </div>
          )}

          {/* TAB 2: CONTENT & MEDIA */}
          {activeTab === "content" && (
            <div className="space-y-4 animate-in fade-in duration-150">
              <ImageUploadInput
                label="Featured Header Image"
                value={formData.featuredImage}
                onChange={(featuredImage) => setFormData({ ...formData, featuredImage })}
                helperText="Cover banner displayed at the top of the article and social share cards."
                recommendedDimension="1200x630px (16:9 / OG)"
              />

              <FormField
                label="Article Excerpt"
                required
                tooltip="Concise summary shown on blog feed cards, Google search snippets, and RSS previews."
                charCount={{ current: formData.excerpt.length, optimal: { min: 100, max: 160 }, max: 200 }}
              >
                <textarea
                  required
                  rows={2}
                  value={formData.excerpt}
                  onChange={(e) => setFormData({ ...formData, excerpt: e.target.value })}
                  placeholder="Compelling 2-sentence hook displayed in article feed cards."
                  className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
                />
              </FormField>

              <FormField
                label="Article Body (Markdown Supported)"
                required
                tooltip="Full article content formatted in Markdown (supports ## headings, code blocks, bullet points, and links)."
                charCount={{ current: formData.content.length, optimal: { min: 500, max: 8000 } }}
                helperText={`${wordCount} words • Estimated ${Math.max(1, Math.ceil(wordCount / 200))} min read`}
              >
                <textarea
                  required
                  rows={10}
                  value={formData.content}
                  onChange={(e) => setFormData({ ...formData, content: e.target.value })}
                  placeholder="Write in Markdown format (## Headings, code blocks, bullet points)..."
                  className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary font-mono focus:outline-none focus:border-[var(--color-accent)] leading-relaxed"
                />
              </FormField>
            </div>
          )}

          {/* TAB 3: TAGS & SEO */}
          {activeTab === "seo" && (
            <div className="space-y-4 animate-in fade-in duration-150">
              <ArrayInput
                label="Article Tags & Topics"
                items={formData.tags}
                onChange={(tags) => setFormData({ ...formData, tags })}
                placeholder="Add tag (e.g. Next.js) and press Enter..."
                helperText="Tags help categorize content and connect related reading recommendations."
              />

              <SeoHelperInputs
                metaTitle={formData.metaTitle}
                onChangeMetaTitle={(metaTitle) => setFormData({ ...formData, metaTitle })}
                metaDescription={formData.metaDescription}
                onChangeMetaDescription={(metaDescription) => setFormData({ ...formData, metaDescription })}
                canonicalPath={`/blog/${formData.slug}`}
                fallbackTitle={formData.title}
                fallbackDescription={formData.excerpt}
              />
            </div>
          )}
        </form>
      </Modal>

      {/* Delete Confirmation Dialog */}
      <ConfirmDialog
        isOpen={Boolean(deleteId)}
        onClose={() => setDeleteId(null)}
        onConfirm={handleDelete}
        title="Delete Article"
        description="Are you sure you want to delete this article? Once deleted, the URL may return a 404 error."
        confirmText="Delete Article"
      />
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { AdminHeader } from "@/components/admin/AdminHeader";
import { DataTable, Column } from "@/components/admin/DataTable";
import { Modal } from "@/components/admin/Modal";
import { ConfirmDialog } from "@/components/admin/ConfirmDialog";
import { ImageUploadInput } from "@/components/admin/ImageUploadInput";
import { useToast } from "@/components/admin/Toast";
import { Button } from "@/components/ui/Button";
import {
  Edit2,
  Trash2,
  Plus,
  Building2,
  ExternalLink,
  CheckCircle2,
  EyeOff,
  Star,
} from "lucide-react";

interface ClientFormData {
  name: string;
  slug: string;
  logoUrl: string;
  industry: string;
  website: string;
  tagline: string;
  description: string;
  aboutPartnership: string;
  servicesProvided: string;
  partnershipYear: string;
  companySize: string;
  location: string;
  testimonialQuote: string;
  testimonialAuthor: string;
  testimonialRole: string;
  keyAchievements: string;
  technologies: string;
  caseStudySlug: string;
  isFeatured: boolean;
  isActive: boolean;
  order: number;
}

const DEFAULT_FORM: ClientFormData = {
  name: "",
  slug: "",
  logoUrl: "",
  industry: "Technology",
  website: "",
  tagline: "",
  description: "",
  aboutPartnership: "",
  servicesProvided: "",
  partnershipYear: "",
  companySize: "",
  location: "",
  testimonialQuote: "",
  testimonialAuthor: "",
  testimonialRole: "",
  keyAchievements: "",
  technologies: "",
  caseStudySlug: "",
  isFeatured: true,
  isActive: true,
  order: 1,
};

export default function ClientsAdminPage() {
  const [clients, setClients] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingClient, setEditingClient] = useState<any | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [formLoading, setFormLoading] = useState(false);
  const [formError, setFormError] = useState("");
  const { addToast } = useToast();

  const [formData, setFormData] = useState<ClientFormData>(DEFAULT_FORM);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const res = await fetch("/api/admin/clients");
      const data = await res.json();
      if (res.ok) setClients(data.clients || []);
    } catch (err) {
      console.error("Error fetching clients", err);
      addToast("Failed to fetch clients", "error");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchClients();
  }, []);

  const openCreateModal = () => {
    setEditingClient(null);
    setFormData({
      ...DEFAULT_FORM,
      order: clients.length + 1,
    });
    setFormError("");
    setIsModalOpen(true);
  };

  const openEditModal = (client: any) => {
    setEditingClient(client);
    setFormData({
      name: client.name || "",
      slug: client.slug || "",
      logoUrl: client.logoUrl || "",
      industry: client.industry || "Enterprise SaaS",
      website: client.website || "",
      tagline: client.tagline || "",
      description: client.description || "",
      aboutPartnership: client.aboutPartnership || "",
      servicesProvided: Array.isArray(client.servicesProvided)
        ? client.servicesProvided.join(", ")
        : client.servicesProvided || "",
      partnershipYear: client.partnershipYear || "",
      companySize: client.companySize || "",
      location: client.location || "",
      testimonialQuote: client.testimonialQuote || client.testimonial?.quote || "",
      testimonialAuthor: client.testimonialAuthor || client.testimonial?.authorName || "",
      testimonialRole: client.testimonialRole || client.testimonial?.authorRole || "",
      keyAchievements: Array.isArray(client.keyAchievements)
        ? client.keyAchievements.join("\n")
        : client.keyAchievements || "",
      technologies: Array.isArray(client.technologies)
        ? client.technologies.join(", ")
        : client.technologies || "",
      caseStudySlug: client.caseStudySlug || "",
      isFeatured: client.isFeatured ?? true,
      isActive: client.isActive ?? true,
      order: client.order ?? 0,
    });
    setFormError("");
    setIsModalOpen(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setFormLoading(true);
    setFormError("");

    try {
      const payload = {
        ...formData,
        servicesProvided: formData.servicesProvided
          .split(",")
          .map((s) => s.trim())
          .filter(Boolean),
        technologies: formData.technologies
          .split(",")
          .map((t) => t.trim())
          .filter(Boolean),
        keyAchievements: formData.keyAchievements
          .split("\n")
          .map((k) => k.trim())
          .filter(Boolean),
      };

      const url = editingClient
        ? `/api/admin/clients/${editingClient._id}`
        : "/api/admin/clients";
      const method = editingClient ? "PUT" : "POST";

      const res = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      const data = await res.json();
      if (res.ok) {
        setIsModalOpen(false);
        addToast(
          editingClient ? "Client updated successfully" : "New client brand added",
          "success"
        );
        fetchClients();
      } else {
        setFormError(data.error || "Failed to save client");
        addToast(data.error || "Failed to save client", "error");
      }
    } catch (err: any) {
      setFormError("An unexpected error occurred");
      addToast("An unexpected error occurred", "error");
    } finally {
      setFormLoading(false);
    }
  };

  const toggleFeatured = async (client: any) => {
    const nextFeatured = !client.isFeatured;
    setClients((prev) =>
      prev.map((c) => (c._id === client._id ? { ...c, isFeatured: nextFeatured } : c))
    );
    try {
      const res = await fetch(`/api/admin/clients/${client._id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ isFeatured: nextFeatured }),
      });
      if (!res.ok) throw new Error("Update failed");
      addToast(
        nextFeatured
          ? `Added "${client.name}" to logo marquee`
          : `Removed "${client.name}" from logo marquee`,
        "success"
      );
    } catch (e) {
      setClients((prev) =>
        prev.map((c) => (c._id === client._id ? { ...c, isFeatured: client.isFeatured } : c))
      );
      addToast("Failed to update marquee status", "error");
    }
  };

  const toggleActive = async (client: any) => {
    const nextActive = !client.isActive;
    setClients((prev) =>
      prev.map((c) => (c._id === client._id ? { ...c, isActive: nextActive } : c))
    );
    try {
      const res = await fetch(`/api/admin/clients/${client._id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ isActive: nextActive }),
      });
      if (!res.ok) throw new Error("Update failed");
      addToast(
        nextActive ? `"${client.name}" is now active` : `"${client.name}" is now hidden`,
        "success"
      );
    } catch (e) {
      setClients((prev) =>
        prev.map((c) => (c._id === client._id ? { ...c, isActive: client.isActive } : c))
      );
      addToast("Failed to update active status", "error");
    }
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    try {
      const res = await fetch(`/api/admin/clients/${deleteId}`, { method: "DELETE" });
      if (res.ok) {
        setDeleteId(null);
        addToast("Client deleted successfully", "success");
        fetchClients();
      } else {
        addToast("Failed to delete client", "error");
      }
    } catch (err) {
      console.error("Failed to delete client", err);
      addToast("Failed to delete client", "error");
    }
  };

  const columns: Column<any>[] = [
    {
      header: "Order",
      accessorKey: "order",
      className: "w-14 font-mono text-center text-xs text-text-muted",
    },
    {
      header: "Client & Logo",
      cell: (row) => (
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-lg bg-surface-2 border border-[var(--color-border)] p-1.5 flex items-center justify-center text-text-muted shrink-0">
            {row.logoUrl ? (
              <img src={row.logoUrl} alt={row.name} className="w-full h-full object-contain" />
            ) : (
              <Building2 size={18} className="text-text-muted" />
            )}
          </div>
          <div>
            <div className="font-semibold text-text-primary text-xs">{row.name}</div>
            <div className="text-[11px] text-text-muted">{row.industry}</div>
          </div>
        </div>
      ),
    },
    {
      header: "Marquee",
      cell: (row) => (
        <button
          type="button"
          onClick={() => toggleFeatured(row)}
          title={row.isFeatured ? "Click to remove from Marquee" : "Click to show in Marquee"}
          className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold border transition-all ${
            row.isFeatured
              ? "bg-purple-500/10 border-purple-500/30 text-purple-600 hover:bg-purple-500/20"
              : "bg-surface-2 border-transparent text-text-muted hover:border-[var(--color-border)]"
          }`}
        >
          <Star size={11} className={row.isFeatured ? "fill-purple-600 text-purple-600" : ""} />
          {row.isFeatured ? "In Marquee" : "Standard"}
        </button>
      ),
    },
    {
      header: "Status",
      cell: (row) => (
        <button
          type="button"
          onClick={() => toggleActive(row)}
          className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11px] font-semibold transition-all ${
            row.isActive
              ? "bg-emerald-500/10 text-emerald-500 hover:bg-emerald-500/20 border border-emerald-500/20"
              : "bg-zinc-500/10 text-zinc-400 hover:bg-zinc-500/20 border border-zinc-500/20"
          }`}
          title="Click to toggle visibility"
        >
          {row.isActive ? <CheckCircle2 size={12} /> : <EyeOff size={12} />}
          {row.isActive ? "Active" : "Hidden"}
        </button>
      ),
    },
    {
      header: "Actions",
      className: "text-right",
      cell: (row) => {
        const clientSlug = row.slug || (row.name || "client").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
        return (
          <div className="flex items-center justify-end gap-1.5">
            <a
              href={`/clients/${clientSlug}`}
              target="_blank"
              rel="noreferrer"
              className="p-1.5 rounded-md hover:bg-surface-3 text-text-muted hover:text-[var(--color-accent-dark)]"
              title="View Live Profile Page"
            >
              <ExternalLink size={14} />
            </a>
            {row.website && (
              <a
                href={row.website}
                target="_blank"
                rel="noreferrer"
                className="p-1.5 rounded-md hover:bg-surface-3 text-text-muted hover:text-text-primary"
                title="Visit Company Website"
              >
                <Building2 size={14} />
              </a>
            )}
            <button
              onClick={() => openEditModal(row)}
              className="p-1.5 rounded-md hover:bg-surface-3 text-text-secondary hover:text-text-primary transition-colors"
              title="Edit"
            >
              <Edit2 size={14} />
            </button>
            <button
              onClick={() => setDeleteId(row._id)}
              className="p-1.5 rounded-md hover:bg-red-500/10 text-text-muted hover:text-red-600 transition-colors"
              title="Delete"
            >
              <Trash2 size={14} />
            </button>
          </div>
        );
      },
    },
  ];

  return (
    <div className="flex-1 flex flex-col">
      <AdminHeader
        title="Client Brands & Partners"
        description="Add and manage client logos displayed in homepage marquees and social proof"
        actionButton={{
          label: "Add Client",
          onClick: openCreateModal,
          icon: Plus,
        }}
        onRefresh={fetchClients}
        isLoading={isLoading}
      />

      <div className="p-6 sm:p-8 max-w-7xl">
        <DataTable
          columns={columns}
          data={clients}
          searchPlaceholder="Search clients by name..."
          searchKey="name"
          isLoading={isLoading}
          emptyMessage="No clients added yet."
        />
      </div>

      {/* Modal */}
      <Modal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        title={editingClient ? "Edit Client" : "Add New Client"}
        description="Provide client brand identity, logo, and marquee presence"
        maxWidth="lg"
        footer={
          <div className="flex items-center justify-end gap-3 w-full">
            <button
              type="button"
              onClick={() => setIsModalOpen(false)}
              className="px-4 py-2 text-xs font-semibold rounded-lg border border-[var(--color-border)] text-text-secondary hover:bg-surface-2 transition-colors"
            >
              Cancel
            </button>
            <Button
              type="submit"
              form="client-modal-form"
              size="sm"
              disabled={formLoading}
              className="text-xs font-semibold shadow-sm"
            >
              {formLoading ? "Saving..." : editingClient ? "Update Client" : "Create Client"}
            </Button>
          </div>
        }
      >
        {formError && (
          <div className="mb-4 p-3 bg-red-500/10 border border-red-500/20 text-red-600 text-xs rounded-lg">
            {formError}
          </div>
        )}

        <form id="client-modal-form" onSubmit={handleSave} className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-text-primary mb-1 uppercase tracking-wider">
              Client / Brand Name *
            </label>
            <input
              type="text"
              required
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              placeholder="e.g. Fintech Ventures"
              className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)] font-medium"
            />
          </div>

          <ImageUploadInput
            label="Client Logo"
            value={formData.logoUrl}
            onChange={(url) => setFormData({ ...formData, logoUrl: url })}
            helperText="Upload transparent PNG or SVG logo for crisp display"
          />

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-text-primary mb-1 uppercase tracking-wider">
                Industry
              </label>
              <input
                type="text"
                value={formData.industry}
                onChange={(e) => setFormData({ ...formData, industry: e.target.value })}
                placeholder="e.g. HealthTech, AI Infrastructure"
                className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-text-primary mb-1 uppercase tracking-wider">
                URL Slug (Optional)
              </label>
              <input
                type="text"
                value={formData.slug}
                onChange={(e) => setFormData({ ...formData, slug: e.target.value })}
                placeholder="e.g. finflow-labs (auto-generated if empty)"
                className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary font-mono focus:outline-none focus:border-[var(--color-accent)]"
              />
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-text-primary mb-1 uppercase tracking-wider">
                Website URL
              </label>
              <input
                type="url"
                value={formData.website}
                onChange={(e) => setFormData({ ...formData, website: e.target.value })}
                placeholder="https://..."
                className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary font-mono focus:outline-none focus:border-[var(--color-accent)]"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-text-primary mb-1 uppercase tracking-wider">
                Location & HQ
              </label>
              <input
                type="text"
                value={formData.location}
                onChange={(e) => setFormData({ ...formData, location: e.target.value })}
                placeholder="e.g. San Francisco, CA"
                className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
              />
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-text-primary mb-1 uppercase tracking-wider">
                Partnership Year / Timeline
              </label>
              <input
                type="text"
                value={formData.partnershipYear}
                onChange={(e) => setFormData({ ...formData, partnershipYear: e.target.value })}
                placeholder="e.g. 2023 - Present"
                className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-text-primary mb-1 uppercase tracking-wider">
                Company Size
              </label>
              <input
                type="text"
                value={formData.companySize}
                onChange={(e) => setFormData({ ...formData, companySize: e.target.value })}
                placeholder="e.g. 150+ Employees"
                className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-semibold text-text-primary mb-1 uppercase tracking-wider">
              Tagline / Value Proposition
            </label>
            <input
              type="text"
              value={formData.tagline}
              onChange={(e) => setFormData({ ...formData, tagline: e.target.value })}
              placeholder="e.g. Autonomous financial reconciliation and real-time ledger intelligence."
              className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
            />
          </div>

          <div>
            <label className="block text-xs font-semibold text-text-primary mb-1 uppercase tracking-wider">
              About Client Organization
            </label>
            <textarea
              rows={2}
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              placeholder="Overview of the client company..."
              className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
            />
          </div>

          <div>
            <label className="block text-xs font-semibold text-text-primary mb-1 uppercase tracking-wider">
              The Engineering Partnership & Scope
            </label>
            <textarea
              rows={3}
              value={formData.aboutPartnership}
              onChange={(e) => setFormData({ ...formData, aboutPartnership: e.target.value })}
              placeholder="What MARK engineered, designed, and deployed for this client..."
              className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
            />
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-text-primary mb-1 uppercase tracking-wider">
                Services Delivered (comma-separated)
              </label>
              <input
                type="text"
                value={formData.servicesProvided}
                onChange={(e) => setFormData({ ...formData, servicesProvided: e.target.value })}
                placeholder="Cloud Architecture, Web App, APIs"
                className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-text-primary mb-1 uppercase tracking-wider">
                Technologies (comma-separated)
              </label>
              <input
                type="text"
                value={formData.technologies}
                onChange={(e) => setFormData({ ...formData, technologies: e.target.value })}
                placeholder="Next.js, TypeScript, PostgreSQL, AWS"
                className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
              />
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-text-primary mb-1 uppercase tracking-wider">
                Key Achievements (one per line)
              </label>
              <textarea
                rows={3}
                value={formData.keyAchievements}
                onChange={(e) => setFormData({ ...formData, keyAchievements: e.target.value })}
                placeholder="Scaled to 2.5M daily ops&#10;Sub-10ms ledger SLA&#10;SOC2 Type II compliance"
                className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-text-primary mb-1 uppercase tracking-wider">
                Associated Case Study Slug (Optional)
              </label>
              <input
                type="text"
                value={formData.caseStudySlug}
                onChange={(e) => setFormData({ ...formData, caseStudySlug: e.target.value })}
                placeholder="e.g. finflow-core"
                className="w-full px-3 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary font-mono focus:outline-none focus:border-[var(--color-accent)] mb-3"
              />
              <label className="block text-xs font-semibold text-text-primary mb-1 uppercase tracking-wider">
                Display Order
              </label>
              <input
                type="number"
                value={formData.order}
                onChange={(e) => setFormData({ ...formData, order: Number(e.target.value) })}
