      await connectToDatabase();
      unreadCount = await Message.countDocuments({ status: "new" });
    } catch (err) {
      // ignore
    }
  }

  return (
    <ToastProvider>
      <div className="min-h-screen bg-surface-2 text-text-primary flex flex-col lg:flex-row">
