    </ToastProvider>
  );
}

"use client";

import { useEffect, useState, useRef } from "react";
import { AdminHeader } from "@/components/admin/AdminHeader";
import { ConfirmDialog } from "@/components/admin/ConfirmDialog";
import { StatusBreakdownBar } from "@/components/admin/StatusBreakdownBar";
import { useToast } from "@/components/admin/Toast";
import { Button } from "@/components/ui/Button";
import {
  Upload,
  Copy,
  Check,
  Trash2,
  Image as ImageIcon,
  Loader2,
  ExternalLink,
  Search,
} from "lucide-react";

export default function MediaAdminPage() {
  const [mediaList, setMediaList] = useState<any[]>([]);
  const [storageFilter, setStorageFilter] = useState("all");
  const [isLoading, setIsLoading] = useState(true);
  const [isUploading, setIsUploading] = useState(false);
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { success, error: toastError } = useToast();

  const fetchMedia = async () => {
    setIsLoading(true);
    try {
      const res = await fetch("/api/admin/media");
      const data = await res.json();
      if (res.ok) setMediaList(data.media || []);
    } catch (err) {
      console.error("Error fetching media", err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchMedia();
  }, []);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setIsUploading(true);
    let successCount = 0;
    try {
      for (let i = 0; i < files.length; i++) {
        const formData = new FormData();
        formData.append("file", files[i]);

        const res = await fetch("/api/admin/upload", {
          method: "POST",
          body: formData,
        });
        if (res.ok) successCount++;
      }
      if (successCount > 0) {
        success(`${successCount} asset${successCount > 1 ? "s" : ""} uploaded successfully`);
      } else {
        toastError("Upload failed. Check file formats and network.");
      }
      fetchMedia();
    } catch (err) {
      console.error("Error uploading files", err);
      toastError("An error occurred during file upload.");
    } finally {
      setIsUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  const copyToClipboard = (url: string, id: string) => {
    navigator.clipboard.writeText(url);
    setCopiedId(id);
    success("Image asset URL copied to clipboard");
    setTimeout(() => setCopiedId(null), 2000);
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    try {
      const res = await fetch(`/api/admin/media?id=${deleteId}`, { method: "DELETE" });
      if (res.ok) {
        setDeleteId(null);
        success("Asset removed from media library");
        fetchMedia();
      } else {
        toastError("Failed to delete media asset");
      }
    } catch (err) {
      console.error("Failed to delete media", err);
      toastError("Error deleting media asset");
    }
  };

  const filteredMedia = mediaList.filter((m) => {
    const matchesSearch = (m.originalName || m.filename).toLowerCase().includes(searchQuery.toLowerCase());
    if (!matchesSearch) return false;
    if (storageFilter === "cloudinary") return Boolean(m.publicId);
    if (storageFilter === "local") return !m.publicId;
    return true;
  });

  return (
    <div className="flex-1 flex flex-col">
      <AdminHeader
        title="Media & File Library"
        description="Upload, view, manage, and copy URLs of website images and assets"
        actionButton={{
          label: isUploading ? "Uploading..." : "Upload Images",
          onClick: () => fileInputRef.current?.click(),
          icon: Upload,
        }}
        onRefresh={fetchMedia}
        isLoading={isLoading}
      />

      <input
        ref={fileInputRef}
        type="file"
        multiple
        accept="image/*"
        onChange={handleFileUpload}
        className="hidden"
      />

      <div className="p-6 sm:p-8 space-y-6 max-w-7xl">
        {/* Drag and Drop Zone */}
        <div
          onClick={() => fileInputRef.current?.click()}
          className="border-2 border-dashed border-[var(--color-border)] hover:border-[var(--color-accent)] bg-surface-1 rounded-2xl p-8 flex flex-col items-center justify-center text-center cursor-pointer transition-all hover:bg-surface-2 group"
        >
          {isUploading ? (
            <div className="flex flex-col items-center">
              <Loader2 size={32} className="animate-spin text-[var(--color-accent-dark)] mb-3" />
              <p className="text-sm font-semibold text-text-primary">Uploading selected assets...</p>
            </div>
          ) : (
            <div className="flex flex-col items-center">
              <div className="w-12 h-12 rounded-xl bg-surface-2 border border-[var(--color-border)] flex items-center justify-center text-text-muted mb-3 group-hover:scale-105 transition-transform shadow-sm">
                <Upload size={22} className="text-[var(--color-accent-dark)]" />
              </div>
              <p className="text-sm font-bold text-text-primary">Click or drop files to upload to media library</p>
              <p className="text-xs text-text-muted mt-1">Supports PNG, JPG, SVG, WebP up to 10MB each</p>
            </div>
          )}
        </div>

        {/* Storage Breakdown & Filtering */}
        <StatusBreakdownBar
          items={[
            { id: "all", label: "All Media", count: mediaList.length },
            { id: "cloudinary", label: "Cloudinary CDN", count: mediaList.filter((m) => Boolean(m.publicId)).length, color: "blue" },
            { id: "local", label: "Local Storage", count: mediaList.filter((m) => !m.publicId).length, color: "zinc" },
          ]}
          activeFilter={storageFilter}
          onFilterChange={setStorageFilter}
        />

        {/* Media Dimension Quick Reference Guide */}
        <div className="bg-surface-1 border border-[var(--color-border)] rounded-xl p-4 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 text-xs">
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-lg bg-[var(--color-accent)]/10 text-[var(--color-accent-dark)] flex items-center justify-center font-bold shrink-0">
              📐
            </div>
            <div>
              <p className="font-bold text-text-primary">Website Dimension Recommendation Cheatsheet</p>
              <p className="text-text-muted">Upload assets optimized for each section to ensure lightning-fast page loading:</p>
            </div>
          </div>
          <div className="flex flex-wrap gap-2 text-[11px]">
            <span className="px-2 py-1 rounded bg-surface-2 border border-[var(--color-border)] text-text-secondary">
              <strong className="text-text-primary">Heroes:</strong> 1920×1080px
            </span>
            <span className="px-2 py-1 rounded bg-surface-2 border border-[var(--color-border)] text-text-secondary">
              <strong className="text-text-primary">Case Studies:</strong> 1600×1000px
            </span>
            <span className="px-2 py-1 rounded bg-surface-2 border border-[var(--color-border)] text-text-secondary">
              <strong className="text-text-primary">Blog Covers:</strong> 1200×630px
            </span>
            <span className="px-2 py-1 rounded bg-surface-2 border border-[var(--color-border)] text-text-secondary">
              <strong className="text-text-primary">Team / Avatars:</strong> 500×500px
            </span>
          </div>
        </div>

        {/* Search Bar */}
        <div className="flex items-center justify-between gap-4 bg-surface-1 p-4 rounded-xl border border-[var(--color-border)]">
          <div className="relative flex-1 max-w-sm">
            <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-text-muted" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search uploaded files by name..."
              className="w-full pl-9 pr-4 py-2 text-xs bg-surface-2 border border-[var(--color-border)] rounded-lg text-text-primary focus:outline-none focus:border-[var(--color-accent)]"
            />
          </div>
          <span className="text-xs text-text-muted font-mono">{filteredMedia.length} Files</span>
        </div>

        {/* Media Grid */}
        {isLoading ? (
          <div className="p-16 text-center text-text-muted">
            <div className="inline-block h-6 w-6 animate-spin rounded-full border-2 border-[var(--color-accent-dark)] border-r-transparent mb-2" />
            <p className="text-xs">Loading media assets...</p>
          </div>
        ) : filteredMedia.length === 0 ? (
          <div className="bg-surface-1 border border-[var(--color-border)] rounded-2xl p-16 text-center text-text-muted">
            <ImageIcon size={36} className="mx-auto mb-2 text-text-muted/60" />
            <p className="text-sm font-semibold text-text-primary mb-1">No media files found</p>
            <p className="text-xs text-text-muted">Upload images to reuse them across services, case studies, and blogs.</p>
          </div>
        ) : (
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-4">
            {filteredMedia.map((item) => {
              const isCopied = copiedId === item._id;
              const sizeInKb = Math.round(item.size / 1024);

              return (
                <div
                  key={item._id}
                  className="group relative bg-surface-1 border border-[var(--color-border)] rounded-xl overflow-hidden hover:border-black/20 hover:shadow-md transition-all flex flex-col"
                >
                  {/* Thumbnail Image */}
                  <div className="w-full h-32 bg-surface-2 flex items-center justify-center overflow-hidden relative">
                    <img
                      src={item.url}
                      alt={item.originalName}
                      className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                    />

                    {/* Storage Badge */}
                    <div className="absolute top-1.5 right-1.5 px-1.5 py-0.5 rounded text-[9px] font-bold uppercase tracking-wider bg-black/60 text-white backdrop-blur-sm pointer-events-none">
                      {item.publicId ? "Cloudinary" : "Local"}
                    </div>

                    {/* Hover Quick Actions */}
                    <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2">
                      <button
                        onClick={() => copyToClipboard(item.url, item._id)}
                        className="p-2 bg-white text-text-primary rounded-lg shadow-sm hover:bg-surface-2 transition-all"
                        title="Copy Public URL"
                      >
                        {isCopied ? <Check size={14} className="text-emerald-600" /> : <Copy size={14} />}
                      </button>
                      <a
                        href={item.url}
                        target="_blank"
                        rel="noreferrer"
                        className="p-2 bg-white text-text-primary rounded-lg shadow-sm hover:bg-surface-2 transition-all"
                        title="Open Full Image"
                      >
                        <ExternalLink size={14} />
                      </a>
                      <button
                        onClick={() => setDeleteId(item._id)}
                        className="p-2 bg-red-600 text-white rounded-lg shadow-sm hover:bg-red-700 transition-all"
                        title="Delete Image"
                      >
                        <Trash2 size={14} />
                      </button>
                    </div>
                  </div>

                  {/* Metadata */}
                  <div className="p-2.5">
                    <p className="text-[11px] font-semibold text-text-primary truncate" title={item.originalName}>
                      {item.originalName}
                    </p>
                    <div className="flex items-center justify-between text-[10px] text-text-muted mt-0.5 font-mono">
                      <span>{sizeInKb} KB</span>
                      <span>{item.width && item.height ? `${item.width}x${item.height}` : new Date(item.createdAt).toLocaleDateString()}</span>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      <ConfirmDialog
        isOpen={!!deleteId}
        onClose={() => setDeleteId(null)}
        onConfirm={handleDelete}
        message="Are you sure you want to delete this media file permanently?"
      />
    </div>
  );
}

"use client";

import { useEffect, useState, useMemo } from "react";
import { AdminHeader } from "@/components/admin/AdminHeader";
import { DataTable, Column } from "@/components/admin/DataTable";
import { Modal } from "@/components/admin/Modal";
import { ConfirmDialog } from "@/components/admin/ConfirmDialog";
import { StatusBreakdownBar } from "@/components/admin/StatusBreakdownBar";
import { FormField } from "@/components/admin/FormField";
import { useToast } from "@/components/admin/Toast";
import { Button } from "@/components/ui/Button";
import {
  Trash2,
  Eye,
  Mail,
  Phone,
  Calendar,
  DollarSign,
  Tag,
  CheckCircle2,
  AlertCircle,
  Copy,
  Check,
  Plus,
  Download,
  PhoneCall,
  MessageCircle,
  StickyNote,
  Send,
  Clock,
  ExternalLink,
  Filter,
  CheckCheck,
  Layers,
  Zap,
} from "lucide-react";

const VALID_STATUSES = [
  { id: "new", label: "New", color: "rose", badge: "bg-rose-500/10 text-rose-600 border-rose-500/20" },
  { id: "contacted", label: "Contacted", color: "purple", badge: "bg-purple-500/10 text-purple-600 border-purple-500/20" },
  { id: "in_progress", label: "In Progress", color: "amber", badge: "bg-amber-500/10 text-amber-600 border-amber-500/20" },
  { id: "completed", label: "Completed", color: "emerald", badge: "bg-emerald-500/10 text-emerald-600 border-emerald-500/20" },
  { id: "closed", label: "Closed", color: "blue", badge: "bg-blue-500/10 text-blue-600 border-blue-500/20" },
  { id: "spam", label: "Spam", color: "zinc", badge: "bg-zinc-500/10 text-zinc-500 border-zinc-500/20" },
];

const PROJECT_TYPES = [
  "All Types",
  "Web Development",
  "Mobile App Development",
  "ERP & SaaS Systems",
  "AI & Automation",
  "Cloud & DevOps Architecture",
  "Product Engineering & Consulting",
  "Other",
];

const BUDGET_RANGES = [
  "All Budgets",
  "Under $10k",
  "$10k - $25k",
  "$25k - $50k",
  "$50k - $100k",
  "$100k+",
];

export default function MessagesAdminPage() {
  const [messages, setMessages] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState("all");
  const [projectFilter, setProjectFilter] = useState("All Types");
  const [budgetFilter, setBudgetFilter] = useState("All Budgets");
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [viewingMessage, setViewingMessage] = useState<any | null>(null);
  const [editingNotes, setEditingNotes] = useState("");
  const [isSavingNotes, setIsSavingNotes] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [isBulkDeleting, setIsBulkDeleting] = useState(false);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isSubmittingLead, setIsSubmittingLead] = useState(false);

  // New Lead Form State
  const [newLead, setNewLead] = useState({
    name: "",
    email: "",
    phone: "",
    projectType: "Web Development",
    budgetRange: "$10k - $25k",
    message: "",
    status: "new",
    notes: "",
  });

  const { success, error: toastError } = useToast();

  const fetchMessages = async () => {
    setIsLoading(true);
    try {
      const res = await fetch("/api/admin/messages");
      const data = await res.json();
      if (res.ok) setMessages(data.messages || []);
    } catch (err) {
      console.error("Error fetching messages", err);
      toastError("Failed to load inquiries");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchMessages();
  }, []);

  // Quick In-Row Status Update
  const handleInlineStatusChange = async (id: string, newStatus: string) => {
    try {
      const res = await fetch(`/api/admin/messages/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: newStatus }),
      });
      if (res.ok) {
        setMessages((prev) =>
          prev.map((m) => (m._id === id ? { ...m, status: newStatus } : m))
        );
        if (viewingMessage && viewingMessage._id === id) {
          setViewingMessage((prev: any) => ({ ...prev, status: newStatus }));
        }
        success(`Lead status set to ${newStatus.toUpperCase()}`);
      } else {
        toastError("Failed to update status");
      }
    } catch {
      toastError("Error updating status");
    }
  };

  // Internal Notes Update
  const handleSaveNotes = async () => {
    if (!viewingMessage) return;
    setIsSavingNotes(true);
    try {
      const res = await fetch(`/api/admin/messages/${viewingMessage._id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ notes: editingNotes }),
      });
      if (res.ok) {
        setMessages((prev) =>
          prev.map((m) => (m._id === viewingMessage._id ? { ...m, notes: editingNotes } : m))
        );
        setViewingMessage((prev: any) => ({ ...prev, notes: editingNotes }));
        success("Internal notes updated successfully");
      } else {
        toastError("Failed to save notes");
      }
    } catch {
      toastError("Error saving notes");
    } finally {
      setIsSavingNotes(false);
    }
  };

  const copyToClipboard = (text: string, field: string) => {
    navigator.clipboard.writeText(text);
    setCopiedField(field);
    success(`Copied ${field} to clipboard`);
    setTimeout(() => setCopiedField(null), 2000);
  };

  const openViewModal = async (msg: any) => {
    setViewingMessage(msg);
    setEditingNotes(msg.notes || "");
    // If it was 'new', automatically mark as 'read'
    if (msg.status === "new") {
      try {
        await fetch(`/api/admin/messages/${msg._id}`, {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ status: "read" }),
        });
        setMessages((prev) =>
          prev.map((m) => (m._id === msg._id ? { ...m, status: "read" } : m))
        );
        setViewingMessage((prev: any) => ({ ...prev, status: "read" }));
      } catch {
        // ignore
      }
    }
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    try {
      const res = await fetch(`/api/admin/messages/${deleteId}`, { method: "DELETE" });
      if (res.ok) {
        setDeleteId(null);
        if (viewingMessage?._id === deleteId) setViewingMessage(null);
        setMessages((prev) => prev.filter((m) => m._id !== deleteId));
        setSelectedIds((prev) => prev.filter((id) => id !== deleteId));
        success("Inquiry deleted successfully");
      } else {
        toastError("Failed to delete inquiry");
      }
    } catch {
      toastError("Failed to delete message");
    }
  };

  // Bulk Status Update
  const handleBulkStatus = async (status: string) => {
    if (selectedIds.length === 0) return;
    try {
      const res = await fetch("/api/admin/messages", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ids: selectedIds, status }),
      });
      if (res.ok) {
        setMessages((prev) =>
          prev.map((m) => (selectedIds.includes(m._id) ? { ...m, status } : m))
        );
        success(`Updated ${selectedIds.length} lead(s) to ${status.toUpperCase()}`);
        setSelectedIds([]);
      } else {
        toastError("Failed to bulk update status");
      }
    } catch {
      toastError("Error performing bulk update");
    }
  };

  // Bulk Deletion
  const handleBulkDelete = async () => {
    if (selectedIds.length === 0) return;
    try {
      const res = await fetch("/api/admin/messages", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ids: selectedIds }),
      });
      if (res.ok) {
        setMessages((prev) => prev.filter((m) => !selectedIds.includes(m._id)));
        success(`Deleted ${selectedIds.length} lead(s)`);
        setSelectedIds([]);
        setIsBulkDeleting(false);
      } else {
        toastError("Failed to bulk delete leads");
      }
    } catch {
      toastError("Error performing bulk deletion");
    }
  };

  // Manual Lead Creation
  const handleCreateLead = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newLead.name.trim() || !newLead.email.trim()) {
      toastError("Please enter both client name and email address.");
      return;
    }

    setIsSubmittingLead(true);
    try {
      const res = await fetch("/api/admin/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newLead),
      });
      const data = await res.json();
      if (res.ok) {
        setMessages((prev) => [data.message, ...prev]);
        success("New inbound lead logged successfully!");
        setIsAddModalOpen(false);
        setNewLead({
          name: "",
          email: "",
          phone: "",
          projectType: "Web Development",
          budgetRange: "$10k - $25k",
          message: "",
          status: "new",
          notes: "",
        });
      } else {
        toastError(data.error || "Failed to create lead");
      }
    } catch {
      toastError("Error submitting new lead");
    } finally {
      setIsSubmittingLead(false);
    }
  };

  // Export to CSV Functionality
  const handleExportCsv = (leadsToExport: any[]) => {
    if (leadsToExport.length === 0) {
      toastError("No leads available to export.");
      return;
    }

    const headers = [
      "ID",
      "Date",
      "Name",
      "Email",
      "Phone",
      "Service Requested",
      "Budget Range",
      "Status",
      "Client Message",
      "Internal Notes",
    ];

    const rows = leadsToExport.map((m) => [
      `"${m._id}"`,
      `"${new Date(m.createdAt).toISOString()}"`,
      `"${(m.name || "").replace(/"/g, '""')}"`,
      `"${(m.email || "").replace(/"/g, '""')}"`,
      `"${(m.phone || "").replace(/"/g, '""')}"`,
      `"${(m.projectType || "").replace(/"/g, '""')}"`,
      `"${(m.budgetRange || "").replace(/"/g, '""')}"`,
      `"${m.status}"`,
      `"${(m.message || "").replace(/"/g, '""').replace(/\n/g, " ")}"`,
      `"${(m.notes || "").replace(/"/g, '""').replace(/\n/g, " ")}"`,
    ]);

    const csvContent = [headers.join(","), ...rows.map((r) => r.join(","))].join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute(
      "download",
      `mark-leads-${new Date().toISOString().slice(0, 10)}.csv`
    );
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    success(`Exported ${leadsToExport.length} lead(s) to CSV!`);
  };

  // Multi-Filter Logic
  const filteredMessages = useMemo(() => {
    return messages.filter((msg) => {
      // 1. Status Filter
      if (statusFilter !== "all" && msg.status !== statusFilter) return false;

      // 2. Project Type Filter
      if (projectFilter !== "All Types") {
        const pType = (msg.projectType || "").toLowerCase();
        const target = projectFilter.toLowerCase();
        if (!pType.includes(target) && !target.includes(pType)) return false;
      }

      // 3. Budget Filter
      if (budgetFilter !== "All Budgets") {
        const bRange = (msg.budgetRange || "").toLowerCase();
        const targetB = budgetFilter.toLowerCase();
        if (!bRange.includes(targetB) && !targetB.includes(bRange)) return false;
      }

      return true;
    });
  }, [messages, statusFilter, projectFilter, budgetFilter]);

  // Selection helpers
  const allVisibleSelected =
    filteredMessages.length > 0 &&
    filteredMessages.every((m) => selectedIds.includes(m._id));

  const toggleSelectAll = () => {
    if (allVisibleSelected) {
      const visibleIds = new Set(filteredMessages.map((m) => m._id));
      setSelectedIds((prev) => prev.filter((id) => !visibleIds.has(id)));
    } else {
      const newIds = Array.from(
        new Set([...selectedIds, ...filteredMessages.map((m) => m._id)])
      );
      setSelectedIds(newIds);
    }
  };

  const toggleSelectOne = (id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]
    );
  };

  // Helper for WhatsApp Clean Number
  const getWhatsAppLink = (phone: string, name: string, projectType: string) => {
    const cleanPhone = phone.replace(/[^0-9]/g, "");
    const text = encodeURIComponent(
      `Hi ${name}, this is MARK Technologies following up on your ${projectType} inquiry.`
    );
    return `https://wa.me/${cleanPhone}?text=${text}`;
  };

  // Metric Computations
  const totalLeads = messages.length;
  const newLeads = messages.filter((m) => m.status === "new").length;
  const activeLeads = messages.filter((m) =>
    ["contacted", "in_progress"].includes(m.status)
  ).length;
  const convertedLeads = messages.filter((m) => m.status === "completed").length;

  const columns: Column<any>[] = [
    {
      header: (
        <input
          type="checkbox"
          checked={allVisibleSelected}
          onChange={toggleSelectAll}
          className="rounded border-[var(--color-border)] text-[var(--color-accent)] focus:ring-[var(--color-accent)] cursor-pointer"
          title="Select all visible leads"
        />
      ),
      className: "w-10 px-4",
      cell: (row) => (
        <input
          type="checkbox"
          checked={selectedIds.includes(row._id)}
          onChange={(e) => {
            e.stopPropagation();
            toggleSelectOne(row._id);
          }}
          className="rounded border-[var(--color-border)] text-[var(--color-accent)] focus:ring-[var(--color-accent)] cursor-pointer"
        />
      ),
    },
    {
      header: "Lead Contact",
      cell: (row) => (
        <div>
          <div className="flex items-center gap-1.5">
            <span className="font-semibold text-text-primary text-xs">{row.name}</span>
            {row.status === "new" && (
              <span className="inline-block w-2 h-2 rounded-full bg-rose-500 animate-pulse" title="New unaddressed inquiry" />
            )}
          </div>
          <div className="text-[11px] text-text-muted font-mono">{row.email}</div>
          {row.phone && (
            <div className="text-[10px] text-text-secondary flex items-center gap-1 mt-0.5">
              <Phone size={10} className="text-text-muted" />
              <span>{row.phone}</span>
            </div>
          )}
        </div>
      ),
    },
    {
      header: "Service & Budget",
      cell: (row) => (
        <div>
          <span className="inline-block px-2 py-0.5 rounded bg-surface-3 text-[11px] font-medium text-text-primary border border-[var(--color-border)]">
            {row.projectType}
          </span>
          <div className="text-[11px] text-[var(--color-accent-dark)] font-mono font-semibold mt-1">
            {row.budgetRange}
          </div>
        </div>
      ),
    },
    {
      header: "Message Snippet",
      cell: (row) => (
        <div className="max-w-xs">
          <p className="line-clamp-2 text-xs text-text-secondary font-light">
            {row.message}
          </p>
          {row.notes && (
            <div className="mt-1 flex items-center gap-1 text-[10px] text-amber-600 bg-amber-500/10 px-1.5 py-0.5 rounded border border-amber-500/20 w-fit">
              <StickyNote size={10} />
              <span className="truncate max-w-[180px]">{row.notes}</span>
            </div>
          )}
        </div>
      ),
    },
    {
      header: "Status Triage",
      cell: (row) => {
        return (
          <select
            value={row.status}
            onChange={(e) => {
              e.stopPropagation();
              handleInlineStatusChange(row._id, e.target.value);
            }}
            onClick={(e) => e.stopPropagation()}
            className={`px-2.5 py-1 rounded-full text-[11px] font-bold uppercase border cursor-pointer focus:outline-none transition-all ${
              VALID_STATUSES.find((s) => s.id === row.status)?.badge ||
              "bg-zinc-500/10 text-zinc-500"
            }`}
          >
            {VALID_STATUSES.map((st) => (
              <option key={st.id} value={st.id} className="bg-surface-1 text-text-primary normal-case font-normal">
                {st.label}
              </option>
            ))}
          </select>
        );
      },
    },
    {
      header: "Received",
      cell: (row) => (
        <span className="text-[11px] text-text-muted font-mono whitespace-nowrap">
          {new Date(row.createdAt).toLocaleDateString()}
        </span>
      ),
    },
    {
      header: "Actions",
      className: "text-right",
      cell: (row) => (
