"use client";

import { useEffect, useRef } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { SectionHeading } from "@/components/ui/SectionHeading";
import { Monitor, Smartphone, Server, Megaphone, Paintbrush, Layers, Database, Cpu, ArrowUpRight } from "lucide-react";
import Link from "next/link";
import { motion, useMotionTemplate, useMotionValue } from "framer-motion";
import { Parallax } from "@/components/ui/Parallax";


const iconMap: Record<string, React.ComponentType<{ size?: number; strokeWidth?: number; className?: string }>> = {
  Monitor,
  Smartphone,
  Server,
  Megaphone,
  Paintbrush,
  Layers,
  Database,
  Cpu
};

function ServiceCard({ service, index, isLarge }: { service: any, index: number, isLarge: boolean }) {
  const Icon = iconMap[service.icon] || Monitor;

  // Hover gradient effect with Framer Motion
  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);

  function handleMouseMove({ currentTarget, clientX, clientY }: React.MouseEvent) {
    const { left, top } = currentTarget.getBoundingClientRect();
    mouseX.set(clientX - left);
    mouseY.set(clientY - top);
  }

  const speed = index % 2 === 0 ? 1.05 : 0.95;

  return (
    <Parallax speed={speed} className={`service-card opacity-0 translate-y-8 h-full ${isLarge ? "lg:col-span-2" : "lg:col-span-1"}`}>
      <Link href={`/services/${service.slug}`} className="block h-full w-full">
        <div
          onMouseMove={handleMouseMove}
          className="group relative flex h-full w-full flex-col overflow-hidden rounded-[24px] border border-[var(--color-border)] bg-surface-1 p-5 sm:p-6 md:p-8 hover:shadow-2xl transition-all duration-500"
        >
          {/* Framer Motion Hover Spotlight */}
          <motion.div
            className="pointer-events-none absolute -inset-px rounded-[24px] opacity-0 transition duration-300 group-hover:opacity-100 z-0"
            style={{
              background: useMotionTemplate`
                radial-gradient(
                  500px circle at ${mouseX}px ${mouseY}px,
                  rgba(201, 169, 110, 0.15),
                  transparent 80%
                )
              `,
            }}
          />
          {/* Animated Gradient Border on Hover */}
          <div className="absolute inset-0 border-2 border-transparent group-hover:border-[var(--color-accent)]/30 rounded-[24px] transition-colors duration-500 pointer-events-none z-10" />
          {/* Background Mesh (Only on large cards for visual hierarchy) */}
          {isLarge && (
            <div className="absolute right-0 top-0 w-64 h-64 bg-gradient-to-br from-[var(--color-accent)]/10 to-transparent blur-3xl rounded-full -translate-y-1/2 translate-x-1/3 pointer-events-none z-0" />
          )}
          <div className="relative z-20 flex flex-col h-full">
            <div className="flex justify-between items-start mb-8 sm:mb-12">
              <div className="inline-flex h-12 w-12 sm:h-14 sm:w-14 items-center justify-center rounded-2xl bg-surface-2 border border-[var(--color-border)] text-text-secondary group-hover:bg-[var(--color-accent)]/10 group-hover:border-[var(--color-accent)]/30 group-hover:text-[var(--color-accent)] transition-all duration-500 group-hover:scale-110 shrink-0">
                <Icon size={24} strokeWidth={1.5} />
              </div>
              <div className="w-9 h-9 sm:w-10 sm:h-10 rounded-full bg-surface-2 border border-[var(--color-border)] flex items-center justify-center text-text-secondary opacity-0 -translate-x-4 group-hover:opacity-100 group-hover:translate-x-0 group-hover:bg-[var(--color-accent)] group-hover:text-surface-1 group-hover:border-[var(--color-accent)] transition-all duration-500 shrink-0">
                <ArrowUpRight size={18} />
              </div>
            </div>

            <div className="mt-auto">
              <h3 className="mb-3 sm:mb-4 text-xl sm:text-2xl font-display text-text-primary group-hover:text-[var(--color-accent)] transition-colors break-words">
                {service.title}
              </h3>
              <p className="text-text-secondary leading-relaxed text-sm sm:text-[var(--text-body-sm)] break-words">
                {service.shortDescription}
              </p>
            </div>
          </div>
        </div>
      </Link>
    </Parallax>
  );
}

export function ServicesSection({
  servicesData = [],
  hideHeader = false,
  className = "",
}: {
  servicesData?: any[];
  hideHeader?: boolean;
  className?: string;
}) {
  const sectionRef = useRef<HTMLElement>(null);
  const activeServices = servicesData.filter((s) => s.isActive !== false).sort((a, b) => (a.order || 0) - (b.order || 0));

  useEffect(() => {
    if (!sectionRef.current) return;

    gsap.to(".service-card", {
      y: 0,
      opacity: 1,
      duration: 0.8,
      stagger: 0.1,
      ease: "power3.out",
      scrollTrigger: {
        trigger: sectionRef.current,
        start: "top 70%",
        toggleActions: "play reverse play reverse",
      }
    });
  }, []);

  return (
    <section
      ref={sectionRef}
      id="services"
      className={`${className ? className : hideHeader ? "pb-16 md:pb-24 pt-4" : "section-padding"} bg-base relative overflow-hidden`}
    >
      {/* Background Parallax Orb */}
      <div className="absolute inset-0 pointer-events-none -z-10 overflow-hidden">
        <Parallax speed={0.3} className="absolute top-1/2 left-1/4 -translate-y-1/2 w-[50vw] h-[50vw] max-w-[800px] max-h-[800px] rounded-full bg-gradient-to-br from-[var(--color-accent)]/5 to-transparent blur-[120px]" />
      </div>

      <div className="container-site relative z-10">
        {!hideHeader && (
          <SectionHeading
            title="Core Capabilities"
            subtitle="We provide end-to-end engineering teams to bring your product from zero to one, and one to infinity."
            badge="Services"
            align="center"
          />
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 auto-rows-[minmax(280px,auto)] sm:auto-rows-[minmax(320px,auto)] gap-4 sm:gap-6">
          {activeServices.map((service, index) => {
            // Create a gorgeous asymmetric bento layout (e.g. indices 0, 3, 4, 7... span 2 cols on lg)
            const isLarge = index === 0 || index === 3 || index === 4 || index === 7 || index === 10;
            return (
              <ServiceCard key={service._id || service.id || index} service={service} index={index} isLarge={isLarge} />
            );
          })}
        </div>
      </div>
    </section>
  );
}

"use client";

import { useEffect, useRef } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import Link from "next/link";
import { SectionHeading } from "@/components/ui/SectionHeading";
import { Globe, ExternalLink } from "lucide-react";
import { Parallax } from "@/components/ui/Parallax";


interface TeamSectionProps {
  teamData?: any[];
  headingTag?: "h1" | "h2";
}

export function TeamSection({ teamData = [], headingTag = "h2" }: TeamSectionProps) {
  const sectionRef = useRef<HTMLElement>(null);
  const gridRef = useRef<HTMLDivElement>(null);

  const activeMembers = teamData.filter((m: any) => m.isActive !== false).sort((a: any, b: any) => (a.order || 0) - (b.order || 0));

  useEffect(() => {
    if (!sectionRef.current || !gridRef.current || activeMembers.length === 0) return;

    gsap.fromTo(
      gridRef.current.children,
      { y: 50, opacity: 0 },
      {
        y: 0,
        opacity: 1,
        duration: 0.8,
        stagger: 0.15,
        ease: "power3.out",
        scrollTrigger: {
          trigger: sectionRef.current,
          start: "top 70%",
          toggleActions: "play reverse play reverse",
        }
      }
    );
  }, [activeMembers.length]);

  if (activeMembers.length === 0) return null;

  return (
    <section ref={sectionRef} id="team" className="section-padding pt-24 sm:pt-28 md:pt-36 bg-base relative overflow-hidden">
      {/* Background Parallax Orb */}
      <div className="absolute inset-0 pointer-events-none -z-10 overflow-hidden">
        <Parallax speed={0.6} className="absolute top-1/2 right-1/4 -translate-y-1/2 w-[50vw] h-[50vw] max-w-[700px] max-h-[700px] rounded-full bg-gradient-to-tr from-[var(--color-accent)]/5 to-transparent blur-[120px]" />
      </div>

      <div className="container-site relative z-10">
        <SectionHeading
          as={headingTag}
          title="The engineers behind the products."
          subtitle="We don't outsource. Every line of code is written by our in-house team of senior engineers and designers."
          badge="Our Team"
          align="center"
        />

        <div ref={gridRef} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 sm:gap-8">
          {activeMembers.map((member, index) => (
            <Link key={member.slug || member._id || index} href={`/team/${member.slug}`}>
              <div className="group relative h-full flex flex-col p-5 sm:p-6 md:p-8 rounded-2xl bg-surface-1 border border-[var(--color-border)] overflow-hidden transition-all duration-500 hover:border-black/20 hover:bg-surface-2">
                {/* Image / Avatar */}
                <div className="w-20 h-20 sm:w-24 sm:h-24 rounded-full bg-black/5 mb-4 sm:mb-6 flex items-center justify-center text-text-muted/50 text-xl sm:text-2xl font-bold uppercase overflow-hidden border-2 border-transparent group-hover:border-[var(--color-accent-light)] transition-colors duration-500">
                  {member.photo ? (
                    <img src={member.photo} alt={member.name} className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500" />
                  ) : (
                    member.name.substring(0, 2)
                  )}
                </div>

                <h3 className="text-xl sm:text-2xl font-display text-text-primary mb-2 group-hover:text-[var(--color-accent-dark)] transition-colors break-words">{member.name}</h3>
                <p className="text-[var(--text-body-sm)] text-[var(--color-accent)] mb-4 sm:mb-6 break-words">{member.role}</p>

                <div className="flex flex-wrap gap-2 mt-auto mb-8">
                  {(member.techTags || []).slice(0, 3).map((tag: string) => (
                    <span key={tag} className="px-3 py-1 rounded-full bg-black/5 text-xs text-text-secondary border border-black/10 group-hover:border-black/20 transition-colors">
                      {tag}
                    </span>
                  ))}
                  {(member.techTags || []).length > 3 && (
                    <span className="px-3 py-1 rounded-full bg-black/5 text-xs text-text-secondary border border-black/10">
                      +{(member.techTags || []).length - 3}
                    </span>
                  )}
                </div>

                <div className="flex items-center gap-5 mt-auto pt-6 border-t border-[var(--color-border)] group-hover:border-black/10 transition-colors">
                  {member.socialLinks?.linkedin && (
                    <div className="text-text-muted hover:text-[#0A66C2] transition-colors"><ExternalLink size={18} /></div>
                  )}
                  {member.socialLinks?.github && (
                    <div className="text-text-muted hover:text-text-primary transition-colors"><Globe size={18} /></div>
                  )}
                  {member.socialLinks?.twitter && (
                    <div className="text-text-muted hover:text-[#1DA1F2] transition-colors"><ExternalLink size={18} /></div>
                  )}
                </div>
              </div>
            </Link>
          ))}
        </div>
      </div>
    </section>
  );
}

"use client";

