"use client";

import { useEffect, useRef } from "react";
import { prefersReducedMotion } from "@/lib/utils";

/**
 * Initializes Lenis smooth scroll and registers it as GSAP ScrollTrigger's
 * scroller proxy so all scroll-linked animations stay in sync.
 *
 * Call once in the site layout — not per-section.
 */
export function useLenis() {
  const lenisRef = useRef<InstanceType<typeof import("lenis").default> | null>(null);

  useEffect(() => {
    if (prefersReducedMotion()) return;

    let animationId: number;

    const init = async () => {
      const Lenis = (await import("lenis")).default;
      const gsapModule = await import("gsap");
      const gsap = gsapModule.default || gsapModule;
      const { ScrollTrigger } = await import("gsap/ScrollTrigger");

      gsap.registerPlugin(ScrollTrigger);

      const lenis = new Lenis({
        lerp: 0.1,
        smoothWheel: true,
      });

      lenisRef.current = lenis;

      // Connect Lenis to ScrollTrigger
      lenis.on("scroll", ScrollTrigger.update);

      gsap.ticker.add((time: number) => {
        lenis.raf(time * 1000);
      });

      gsap.ticker.lagSmoothing(0);
    };

    init();

    return () => {
      if (lenisRef.current) {
        lenisRef.current.destroy();
        lenisRef.current = null;
      }
    };
  }, []);

  return lenisRef;
}

"use client";

import { useEffect, useRef, useCallback, type RefObject } from "react";
import { MOUSE_PARALLAX } from "@/lib/animations";
import { lerp, prefersReducedMotion } from "@/lib/utils";

/**
 * Magnetic button effect — element follows cursor within a bounded radius,
 * snapping back with spring easing on mouse leave.
 *
 * Attach ref to the interactive element.
 */
export function useMagneticButton<T extends HTMLElement = HTMLButtonElement>(
  strength: number = 0.3
): RefObject<T | null> {
  const ref = useRef<T>(null);

  useEffect(() => {
    if (!ref.current || prefersReducedMotion()) return;

    const element = ref.current;
    let currentX = 0;
    let currentY = 0;
    let targetX = 0;
    let targetY = 0;
    let rafId: number;

    const animate = () => {
      currentX = lerp(currentX, targetX, MOUSE_PARALLAX.dampingFactor);
      currentY = lerp(currentY, targetY, MOUSE_PARALLAX.dampingFactor);

      element.style.transform = `translate(${currentX}px, ${currentY}px)`;

      rafId = requestAnimationFrame(animate);
    };

    const handleMouseMove = (e: MouseEvent) => {
      const rect = element.getBoundingClientRect();
      const centerX = rect.left + rect.width / 2;
      const centerY = rect.top + rect.height / 2;

      const deltaX = (e.clientX - centerX) * strength;
      const deltaY = (e.clientY - centerY) * strength;

      targetX = Math.max(
        -MOUSE_PARALLAX.maxDisplacement,
        Math.min(MOUSE_PARALLAX.maxDisplacement, deltaX)
      );
      targetY = Math.max(
        -MOUSE_PARALLAX.maxDisplacement,
        Math.min(MOUSE_PARALLAX.maxDisplacement, deltaY)
      );
    };

    const handleMouseLeave = () => {
      targetX = 0;
      targetY = 0;
    };

    element.addEventListener("mousemove", handleMouseMove);
    element.addEventListener("mouseleave", handleMouseLeave);
    rafId = requestAnimationFrame(animate);

    return () => {
      element.removeEventListener("mousemove", handleMouseMove);
      element.removeEventListener("mouseleave", handleMouseLeave);
      cancelAnimationFrame(rafId);
      element.style.transform = "";
    };
  }, [strength]);

  return ref;
}

import { jwtVerify, SignJWT } from "jose";
import { cookies } from "next/headers";
import { NextRequest } from "next/server";

const JWT_SECRET = process.env.JWT_SECRET;
if (!JWT_SECRET) {
  throw new Error(
    "SECURITY: JWT_SECRET environment variable is not set. " +
    "Please define JWT_SECRET in your .env.local file with a strong random string (minimum 32 characters)."
  );
}
const encodedSecret = new TextEncoder().encode(JWT_SECRET);

export interface SessionPayload {
  userId: string;
  role: string;
  email: string;
  [key: string]: any;
}

export async function encrypt(payload: SessionPayload) {
  return new SignJWT(payload)
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime("7d")
    .sign(encodedSecret);
}

export async function decrypt(session: string | undefined = "") {
  try {
    const { payload } = await jwtVerify(session, encodedSecret, {
      algorithms: ["HS256"],
    });
    return payload as SessionPayload;
  } catch (_error) {
    return null;
  }
}

export async function getSession() {
  const cookieStore = await cookies();
  const session = cookieStore.get("admin_session")?.value;
  if (!session) return null;
  return await decrypt(session);
}

export async function updateSession(request: NextRequest) {
  const session = request.cookies.get("admin_session")?.value;
  if (!session) return;

  // Refresh the session so it doesn't expire
  const parsed = await decrypt(session);
  if (!parsed) return;
  parsed.expires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const res = new Response("OK");
  res.headers.append(
    "Set-Cookie",
    `admin_session=${await encrypt(parsed)}; Path=/; HttpOnly; SameSite=Lax; Expires=${parsed.expires.toUTCString()}`
  );
  return res;
}
